class Solution {
    public int[][] generateMatrix(int n) {
        int[][] ans = new int[n][n];

        int r1=0, r2=n-1;
        int c1=0, c2=n-1;
        int elem = 1;
        while(r2>=r1 && c2>=c1){
            for(int i=c1; i<=c2; i++){
                ans[r1][i] = elem++;
            }
            for(int j=r1+1; j<=r2-1; j++){
                ans[j][c2] = elem++;
            }
            if(r2>r1 && c2>c1){
                for (int i = c2; i >= c1; i--){
                    ans[r2][i] = elem++;
                }
                for (int j = r2-1; j>=r1+1; j--){
                    ans[j][c1] = elem++;
                }
            }
            r1++;
            r2--;
            c1++;
            c2--;
        }
        return ans;
    }
}

//TC: O(n) + O(n- (n % k)) ~ O(n)
//SC: O(1)

class Solution {
    public ListNode rotateRight(ListNode head, int k) {
        if (head == null || head.next == null || k == 0)
            return head;

        int l = 1; // length of list
        ListNode temp = head;

        // calculate the list's length
        while (temp.next != null) {
            l++;
            temp = temp.next;
        }

        temp.next = head; // make the list cyclic
        k = k % l; // handles the case where k>l
        k = l - k;

        while (k > 0) {
            temp = temp.next;
            k--;
        }
        head = temp.next;
        temp.next = null;

        return head;
    }
}

class Solution {

    // Dynamic programming: TC = O(m*n), SC = O(m*n)
    public int uniquePaths(int m, int n) {
        int[][] dp = new int[m][n];

        // Fill out last row
        for (int j = 0; j < n; j++) {
            dp[m - 1][j] = 1;
        }

        // Fill out last column
        for (int i = 0; i < m; i++) {
            dp[i][n - 1] = 1;
        }

        for (int i = m - 2; i >= 0; i--) {
            for (int j = n - 2; j >= 0; j--) {
                dp[i][j] = dp[i][j + 1] + dp[i + 1][j];
            }
        }
        return dp[0][0];
    }

    // Dynamic programming: TC = O(m*n), SC = O(min(m,n))
    public int uniquePaths2(int m, int n) {
        if (m <= 0 || n <= 0) return 0;

        int[] dp = new int[n];
        for (int i = 0; i < n; i++)
            dp[i] = 1;

        for (int i = 1; i < m; i++)
            for (int j = 1; j < n; j++)
                dp[j] += dp[j - 1];

        return dp[n - 1];
    }

    // Combinatorics: TC = O(min(m,n)), SC = O(1)
    // result = C(m + n, n) = (m + n)! / (m! * n!)
    public int uniquePaths3(int m, int n) {
        if (m <= 0 || n <= 0) return 0;

        if (m < n) return uniquePaths3(n, m);

        m--;
        n--;
        long res = 1;
        for (int i = 1; i <= n; i++) {
            res *= (m + i);
            res /= i;
        }
        return (int)res;
    }
}

//Same as unique paths 1 just one extra condition to return 0 if grid[i][j] == 1

class Solution {

    public int uniquePathsWithObstacles(int[][] grid) {
        return dfs(
            grid,
            0,
            0,
            grid.length,
            grid[0].length,
            new int[grid.length][grid[0].length]
        );
    }

    public int dfs(int[][] grid, int i, int j, int m, int n, int[][] dp) {
        if (i < 0 || j < 0 || i >= m || j >= n || grid[i][j] == 1) {
            return 0;
        }
        if (i == m - 1 && j == n - 1) {
            dp[i][j] = 1;
            return dp[i][j];
        }
        if (dp[i][j] != 0) return dp[i][j];
        int right = dfs(grid, i, j + 1, m, n, dp);
        int left = dfs(grid, i + 1, j, m, n, dp);
        dp[i][j] = right + left;
        return dp[i][j];
    }
}

class Solution {

    public int minPathSum(int[][] grid) {
        int m = grid.length - 1;
        int n = grid[0].length - 1;
        int[][] dp = new int[m + 1][n + 1];
        for (int[] arr : dp) {
            Arrays.fill(arr, -1);
        }
        return helper(grid, m, n, dp);
    }

    public int helper(int[][] grid, int m, int n, int[][] dp) {
        if (m == 0 && n == 0) return grid[0][0];
        if (m == 0) {
            dp[m][n] = grid[m][n] + helper(grid, m, n - 1, dp);
            return dp[m][n];
        }
        if (n == 0) {
            dp[m][n] = grid[m][n] + helper(grid, m - 1, n, dp);
            return dp[m][n];
        }
        if (dp[m][n] != -1) return dp[m][n];
        dp[m][n] =
            grid[m][n] +
            Math.min(helper(grid, m, n - 1, dp), helper(grid, m - 1, n, dp));
        return dp[m][n];
    }
}

class Solution {

    public int[] plusOne(int[] digits) {
        final int len = digits.length;
        int[] newDigits = new int[len + 1];
        int carry = 1;
        int currSum = 0;
        for (int i = len - 1; i >= 0; i--) {
            currSum = digits[i] + carry;
            if (currSum > 9) {
                digits[i] = currSum % 10;
                newDigits[i + 1] = digits[i];
                carry = 1;
            } else {
                digits[i] = currSum;
                newDigits[i + 1] = digits[i];
                carry = 0;
                break;
            }
        }

        if (carry == 1) {
            newDigits[0] = 1;
            return newDigits;
        }

        return digits;
    }
}

class Solution {
    public String addBinary(String a, String b) {
        // Go from right to left
        int len1 = a.length();
        int len2 = b.length();

        int minLen = Math.min(len1, len2);
        int maxLen = Math.max(len1, len2);

        int index1 = len1 - 1;
        int index2 = len2 - 1;

        StringBuilder bld = new StringBuilder();
        boolean carry = false;

        while((index1 >= 0) || (index2 >= 0) || carry) {
            char c1 = (index1 >= 0) ? a.charAt(index1) : '0';
            char c2 = (index2 >= 0) ? b.charAt(index2) : '0';

            char sum;
            if((c1 == '0') && (c2 == '0')) {        // Both zeros
                sum = carry ? '1' : '0';
                carry = false;
            }
            else if((c1 == '1') && (c2 == '1')) {   // Both ones
                sum = carry ? '1' : '0';
                carry = true;
            }
            else {                                  // Any one with a one
                sum = carry ? '0' : '1';
                // carry will be forwarded
            }
            bld.append(sum);

            index1--;
            index2--;
        }

        return bld.reverse().toString();
    }
}

class Solution {
    public List<String> fullJustify(String[] words, int maxWidth) {
        int count = 0;
        List<String> currLine = new ArrayList<>();
        List<String> ans = new ArrayList<>();
        for (String w : words) {
            if (count == 0) {
                count += w.length();
                currLine.add(w);
            } else if (count + 1 + w.length() > maxWidth) {
                ans.add(getLine(currLine, count, maxWidth));
                currLine = new ArrayList<>(List.of(w));
                count = w.length();
            } else {
                count += 1 + w.length();
                currLine.add(w);
            }
        }
        ans.add(getLastLine(currLine, maxWidth));
        return ans;
    }

    private String getLine(List<String> words, int count, int maxWidth) {
        if (words.size() == 0) return "";
        if (words.size() == 1) return words.get(0) + " ".repeat(maxWidth - words.get(0).length());
        int extraSpaces = (maxWidth - count) / (words.size() - 1);
        int remSpaces = (maxWidth - count) % (words.size() - 1);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < words.size() - 1; i++) {
            sb.append(words.get(i)).append(" ");
            sb.append(" ".repeat(extraSpaces));
            if (remSpaces-- > 0)
                sb.append(" ");
        }
        sb.append(words.getLast());
        return sb.toString();
    }

    private String getLastLine(List<String> words, int maxWidth) {
        String wordsStr = String.join(" ", words);
        return wordsStr.toString() + " ".repeat(maxWidth - wordsStr.length());
    }
}

class Solution {
    public int mySqrt(int x) {

        // Linear search way -> loop through for all nums till x
        // then see if their square <= x

        // Binary Search way -> we can optimise our approach by observing
        // that nums till x are sorted

        int left = 0;
        int right = x;
        int mid = 0;
        int probableAns = 0;

        while(left <= right){
            mid = left + (right-left)/2;
            if((long)mid*mid <= (long)x){
                probableAns = mid;
                // let's see if we can find a bigger num
                left = mid+1;
            }
            else if((long)mid*mid > (long)x){
                right = mid-1;
            }
        }

        return probableAns;
    }
}

