class Solution {

    public boolean search(int[] nums, int target) {
        int l = 0, r = nums.length - 1;
        while (l <= r) {
            // to avoid duplicates
            while (l < r && nums[l] == nums[l + 1]) ++l;
            while (l < r && nums[r] == nums[r - 1]) --r;

            int m = l + (r - l) / 2;

            int num = (nums[m] < nums[0]) == (target < nums[0])
                ? nums[m]
                : target < nums[0] ? Integer.MIN_VALUE : Integer.MAX_VALUE;

            if (num < target) {
                l = m + 1;
            } else if (num > target) {
                r = m - 1;
            } else {
                return true;
            }
        }
        return false;
    }
}

//Three pointer approach that we use in in-place reversal of linked list.

class Solution {

    public ListNode deleteDuplicates(ListNode head) {
        ListNode p = null;
        ListNode q = null;
        ListNode r = head;
        while (r != null) {
            if (q != null && q.val == r.val) {
                r = r.next;
                q.next = r;
            } else {
                p = q;
                q = r;
                r = r.next;
            }
        }
        return head;
    }
}

class Solution {
    public int largestRectangleArea(int[] heights) {
      int area = 0, n = heights.length;
      int start;
      Stack<Pair<Integer,Integer>> stack = new Stack<>();
      for(int i=0;i<heights.length;i++){
         int curHt =heights[i];
         start = i;
        while(!stack.isEmpty() && stack.peek().getValue() > curHt){
          Pair<Integer,Integer> pair = stack.pop();
          int index = pair.getKey();
          int h = pair.getValue();
          area = Math.max(area, h * (i - index));
          start = index;
        }
        stack.push(new Pair(start,curHt));
      }

       while(!stack.isEmpty()){
          Pair<Integer,Integer> pair = stack.pop();
          int index = pair.getKey();
          int h = pair.getValue();
          area = Math.max(area, h * (n - index));
       }
        return area;
    }

}

class Solution {
    public ListNode partition(ListNode head, int x) {
        ListNode head1 = new ListNode(); // will store node.value < x
        ListNode head2 = new ListNode(); // will store node.value >= x

        ListNode tail1 = head1, tail2 = head2, curr = head;

        while (curr != null) {
            if (curr.val < x) {
                tail1.next = curr;
                tail1 = tail1.next;
            } else {
                tail2.next = curr;
                tail2 = tail2.next;
            }
            curr = curr.next;
        }
        // at this point the two lists are not connected the way we want them to
        // we'll need to connect the list with values<x to list with values >= x
        // also the last node (tail2) is currently pointing to some random node but it
        // should point to null
        tail1.next = head2.next;
        tail2.next = null;
        return head1.next;
    }
}

class Solution {

    //  Time: O(m+n) | Space: O(1)
    public void merge(int[] nums1, int m, int[] nums2, int n) {
        // Three pointer technique
        int r1 = m-1;
        int r2 = n-1;

        for(int w = m+n-1; w >= 0; w--) {
            if(r1 >= 0 && r2 >= 0) {
                nums1[w] = nums1[r1] > nums2[r2] ? nums1[r1--] : nums2[r2--];
            } else if (r1 >= 0) {
                nums1[w] = nums1[r1--];
            } else {
                nums1[w] = nums2[r2--];
            }
        }
    }
}

