class Solution {
    public List<TreeNode> generateTrees(int n) {
        return generate(1, n);
    }

    private List<TreeNode> generate(int left, int right) {
        if (left > right) {
            List<TreeNode> r = new ArrayList<>();
            r.add(null);
            return r;
        }

        List<TreeNode> res = new ArrayList<>();
        for (int val = left; val <= right; val++) {
            for (TreeNode leftSubtree : generate(left, val - 1)) {
                for (TreeNode rightSubtree: generate(val + 1, right)) {
                    TreeNode root = new TreeNode(val);
                    root.left = leftSubtree;
                    root.right = rightSubtree;
                    res.add(root);
                }
            }
        }

        return res;
    }
}

class Solution {
    public int numTrees(int n) {
        int[] numTree = new int[n+1];
        numTree[0] = numTree[1] = 1;

        for(int nodes = 2; nodes < n+1; nodes++){
            int total = 0;
            for(int root = 1; root < nodes+1; root++){
                int left = root - 1;
                int right = nodes - root;
                total += numTree[left] * numTree[right];
            }
            numTree[nodes] = total;
        }
        return numTree[n];
    }
}

class Solution {

    public boolean isInterleave(String s1, String s2, String s3) {
        if (s1.length() + s2.length() != s3.length()) {
            return false;
        }

        boolean[][] dp = new boolean[s1.length() + 1][s2.length() + 1];
        dp[s1.length()][s2.length()] = true;

        for (int i = dp.length - 1; i >= 0; i--) for (
            int j = dp[0].length - 1;
            j >= 0;
            j--
        ) {
            if (
                i < s1.length() &&
                s1.charAt(i) == s3.charAt(i + j) &&
                dp[i + 1][j]
            ) {
                dp[i][j] = true;
            }
            if (
                j < s2.length() &&
                s2.charAt(j) == s3.charAt(i + j) &&
                dp[i][j + 1]
            ) {
                dp[i][j] = true;
            }
        }

        return dp[0][0];
    }
}

