class Solution {
    // Iterative
    public List<Integer> postorderTraversal(TreeNode root) {
        Stack<TreeNode> stack = new Stack<>();
        stack.add(root);
        Stack<Boolean> visit = new Stack<>();
        visit.add(false);

        List<Integer> res = new ArrayList<>();

        while(!stack.isEmpty()){
            TreeNode curr=stack.pop();
            boolean v = visit.pop();
            if(curr != null){
                if(v != false){
                    res.add(curr.val);
                }else{
                    stack.add(curr);
                    visit.add(true);
                    stack.add(curr.right);
                    visit.add(false);
                    stack.add(curr.left);
                    visit.add(false);
                }
            }
        }
        return res;
    }
}

