class NumArray {
    public int n;
    public int[] tree;

    public NumArray(int[] nums) {
        this.n = nums.length;
        this.tree = new int[2 * this.n];
        buildTree(nums);
    }

    // O(n)
    private void buildTree(int[] nums) {
        // we build the tree from bottom up
        for (int i = n, j = 0; i < 2 * this.n; i++, j++) {
            this.tree[i] = nums[j];
        }
        for (int i = this.n-1; i > 0; i--) {
            this.tree[i] = this.tree[2 * i] + this.tree[2 * i + 1]; // parent value is sum of children values
        }
    }

    // O(logn)
    public void update(int index, int val) {
        index += this.n;
        this.tree[index] = val;
        while (index > 0) {
            int left = index;
            int right = index;
            if ((index % 2 == 0)) {
                // we are on the left node of parent
                right = index + 1;
            } else {
                // we are on the right node of the parent
                left = index -1;
            }
            this.tree[index / 2] = this.tree[right] + this.tree[left]; // parent is updated
            index /= 2;
        }
    }

    // O(logn)
    public int sumRange(int left, int right) {
        int l = left + this.n;
        int r = right + this.n;
        int sum = 0;

        while (l <= r) {
            if ((l % 2) == 1) {
                // l is the right child of his parent,
                // parent includes the sum of l and the right node which is not
                // in the query sum, so we just include this.tree[l] in the sum
                sum += this.tree[l];
                l++; // shrink interval
            }
            if ((r % 2) == 0) {
                // r is the left child of his parent,
                // parent includes the sum of r and the left node which is not
                // in the query sum, so we just include this.tree[r] in the sum
                sum += this.tree[r];
                r--; // shrink interval
            }
            l /= 2;
            r /= 2;
        }
        return sum;
    }
}

class Solution {

    public int maxProfit(int[] prices) {
        Map<String, Integer> cache = new HashMap<>();
        return dfs(prices, cache, 0, true);
    }

    public int dfs(
        int[] prices,
        Map<String, Integer> cache,
        int index,
        boolean buying
    ) {
        if (index >= prices.length) {
            return 0;
        }
        String key = index + "-" + buying;

        if (cache.containsKey(key)) {
            return cache.get(key);
        }

        int cooldown = dfs(prices, cache, index + 1, buying);
        int buyOsell = Integer.MIN_VALUE;

        if (buying) {
            buyOsell = dfs(prices, cache, index + 1, !buying) - prices[index];
        } else {
            buyOsell = dfs(prices, cache, index + 2, !buying) + prices[index];
        }

        cache.put(key, Math.max(buyOsell, cooldown));
        return cache.get(key);
    }
}

// Solution: Dynamic Programming with Memoization

// Time Complexity: O(n^3)
// Extra Space Complexity: O(n^2)
class Solution {

    public int maxCoins(int[] nums) {
        var dp = new int[nums.length][nums.length];

        return burst(nums, 0, nums.length - 1, dp);
    }

    private int burst(int[] nums, int left, int right, int[][] dp) {
        if (left > right) {
            return 0;
        }
        if (dp[left][right] != 0) {
            return dp[left][right];
        }

        for (int i = left; i <= right; i++) {
            int coins = nums[i];

            if (left - 1 >= 0) {
                coins *= nums[left - 1];
            }
            if (right + 1 < nums.length) {
                coins *= nums[right + 1];
            }

            coins +=
                burst(nums, left, i - 1, dp) + burst(nums, i + 1, right, dp);
            dp[left][right] = Math.max(dp[left][right], coins);
        }

        return dp[left][right];
    }
}

class Solution {
    public String removeDuplicateLetters(String s) {
        Set<Character> seen = new HashSet<>();
        HashMap<Character, Integer> last = new HashMap<>();
        for(char c : s.toCharArray()){
            if(!last.containsKey(c))
                last.put(c, s.lastIndexOf(c));
        }
        Stack<Character> stack = new Stack();
        for(int i = 0; i < s.length(); i++){
            char c = s.charAt(i);
            if(seen.contains(c))
                continue;
            while(!stack.isEmpty() && stack.peek() > c && i < last.get(stack.peek()))
                seen.remove(stack.pop());
            stack.push(c);
            seen.add(c);
        }
        StringBuilder sb = new StringBuilder();
        for(char c: stack)
            sb.append(c);
        return sb.toString();
    }
}

