class Solution {

    int index = 0;

    public String decodeString(String s) {

        StringBuilder decoded = new StringBuilder();
        while (index < s.length() && s.charAt(index) != ']') {

            // character is a letter of encoded
            if (!Character.isDigit(s.charAt(index))) decoded.append(s.charAt(index++));

            // character is number or [ ]
            else {
                int k = 0;

                // case: number
                while (index < s.length() && Character.isDigit(s.charAt(index))) k = k * 10 + s.charAt(index++) - '0';

                // case: [
                index++;
                String answer = decodeString(s);

                // case: ]
                index++;

                // add k*encoded to decoded
                while (k-- > 0) decoded.append(answer);
            }
        }
        return new String(decoded);
    }
}

class Solution {
    public double[] calcEquation(List<List<String>> equations, double[] values, List<List<String>> queries) {
        Map<String, List<Pair<String, Double>>> adj = new HashMap<>();
        for (int i = 0; i < equations.size(); i++) {
            List<String> equation = equations.get(i);
            adj.computeIfAbsent(
                    equation.get(0), k -> new ArrayList<>()).add(
                            new Pair<>(equation.get(1), values[i]));
            adj.computeIfAbsent(
                    equation.get(1), k -> new ArrayList<>()).add(
                            new Pair<>(equation.get(0), 1 / values[i]));
        }
        double[] res = new double[queries.size()];
        for (int i = 0; i < queries.size(); i++) {
            List<String> query = queries.get(i);
            res[i] = bfs(adj, query.get(0), query.get(1));
        }
        return res;
    }

    private double bfs(Map<String, List<Pair<String, Double>>> adj, String src, String target) {
        if (!adj.containsKey(src) || !adj.containsKey(target)) {
            return -1.0;
        }
        ArrayDeque<Pair<String, Double>> queue = new ArrayDeque<>();
        Set<String> visited = new HashSet<>();
        queue.addLast(new Pair<>(src, 1.0));
        visited.add(src);
        while (!queue.isEmpty()) {
            Pair<String, Double> item = queue.pollFirst();
            String node = item.getKey();
            Double curWeight = item.getValue();
            if (node.equals(target)) {
                return curWeight;
            }
            for (Pair<String, Double> neighbor : adj.get(node)) {
                String nextNode = neighbor.getKey();
                Double weight = neighbor.getValue();
                if (!visited.contains(nextNode)) {
                    queue.addLast(new Pair<>(nextNode, curWeight * weight));
                    visited.add(nextNode);
                }
            }
        }
        return -1.0;
    }
}

class Solution {
    public String removeKdigits(String num, int k) {
        if(k >= num.length())
            return "0";

        Stack<Character> stack = new Stack<>();
        for(char d: num.toCharArray()){
            while(!stack.empty() && d < stack.peek() && k > 0){
                stack.pop();
                k--;
            }
            stack.push(d);
        }
        while(!stack.empty() && k > 0){
            stack.pop();
            k--;
        }

        StringBuilder res = new StringBuilder();
        while(!stack.empty()){
            res.insert(0, stack.pop());
        }

        for(int i = 0; i < res.length(); i++){
            if(res.charAt(i) != '0'){
                return res.toString().substring(i, res.length());
            }
        }
        return "0";
    }
}

class Solution {
    public boolean validWordAbbreviation(String word, String abbr) {
        int i = 0, j = 0;
        while (i < word.length() && j < abbr.length()) {
            if (word.charAt(i) == abbr.charAt(j)) {
                i++;
                j++;
                continue;
            }
            if (abbr.charAt(j) <= '0' || abbr.charAt(j) > '9')
                return false;
            int num = 0;
            while (j < abbr.length() && Character.isDigit(abbr.charAt(j))) {
                num = num * 10 + abbr.charAt(j) - '0';
                j++;
            }
            i += num;
        }
        return i == word.length() && j == abbr.length();
    }
}

class Solution {
    public int splitArray(int[] nums, int k) {
        int start = 0;
        int end = 0;

        for (int i = 0; i < nums.length; i++) {
            start = Math.max(start, nums[i]);
            end += nums[i];
        }

        while (start < end) {
            int mid = start + (end - start) / 2;

            // calculate how many pieces you can divide this in with this max sum
            int sum = 0;
            int pieces = 1;
            for(int num : nums) {
                if (sum + num > mid) {
                    sum = num;
                    pieces++;
                } else {
                    sum += num;
                }
            }

            if (pieces > k) {
                start = mid + 1;
            } else {
                end = mid;
            }

        }
        return end; // here start == end
    }
}

class Solution {

    // TC = O(n*sum), SC = O(n*sum)
    public boolean canPartition(int[] nums) {
        int sum = 0;
        for (int num : nums) {
            sum += num;
        }
        if (sum % 2 != 0) return false;
        int target = sum / 2;
        boolean[][] dp = new boolean[nums.length + 1][target + 1];
        int n = nums.length;
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= target; j++) {
                if (i == 0 || j == 0) {
                    if (i == 0) dp[i][j] = false; else if (j == 0) dp[i][j] =
                        true;
                } else if (j >= nums[i - 1]) {
                    dp[i][j] = dp[i - 1][j] || dp[i - 1][j - nums[i - 1]];
                } else {
                    dp[i][j] = dp[i - 1][j];
                }
            }
        }
        return dp[n][target];
    }

    // TC = O(n*sum), SC = O(sum)
    public boolean canPartition(int[] nums) {
        int sum = Arrays.stream(nums).sum();
        if (sum % 2 != 0) return false;

        int target = sum / 2;
        boolean[] dp = new boolean[target];
        dp[0] = true;

        for (int no : nums) {
            for (int i = target; i >= no; i--) {
                if (dp[i - no] == true) {
                    if (i == target) return true;
                    dp[i] = true;
                }
            }
        }
        return false;
    }
}

class Solution {

    int[][] dir = { { 0, 1 }, { 0, -1 }, { 1, 0 }, { -1, 0 } };

    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        List<List<Integer>> res = new ArrayList<>();

        int rows = heights.length, cols = heights[0].length;
        boolean[][] pacific = new boolean[rows][cols];
        boolean[][] atlantic = new boolean[rows][cols];

        for (int i = 0; i < cols; i++) {
            dfs(heights, 0, i, Integer.MIN_VALUE, pacific);
            dfs(heights, rows - 1, i, Integer.MIN_VALUE, atlantic);
        }

        for (int i = 0; i < rows; i++) {
            dfs(heights, i, 0, Integer.MIN_VALUE, pacific);
            dfs(heights, i, cols - 1, Integer.MIN_VALUE, atlantic);
        }

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (pacific[i][j] && atlantic[i][j]) {
                    res.add(List.of(i, j));
                }
            }
        }
        return res;
    }

    private void dfs(
        int[][] heights,
        int i,
        int j,
        int prev,
        boolean[][] ocean
    ) {
        if (i < 0 || i >= ocean.length || j < 0 || j >= ocean[0].length) return;
        if (heights[i][j] < prev || ocean[i][j]) return;

        ocean[i][j] = true;
        for (int[] d : dir) {
            dfs(heights, i + d[0], j + d[1], heights[i][j], ocean);
        }
    }
}

class Solution {

    public int characterReplacement(String s, int k) {
        int[] arr = new int[26];
        int ans = 0;
        int max = 0;
        int i = 0;
        for (int j = 0; j < s.length(); j++) {
            arr[s.charAt(j) - 'A']++;
            max = Math.max(max, arr[s.charAt(j) - 'A']);
            if (j - i + 1 - max > k) {
                arr[s.charAt(i) - 'A']--;
                i++;
            }
            ans = Math.max(ans, j - i + 1);
        }
        return ans;
    }
}

class Solution {

    private int[][] grid;

    public Node construct(int[][] grid) {
        this.grid = grid;
        return dfs(0, 0, grid.length);
    }

    private Node dfs(int row, int column, int n) {
        Node node = new Node();

        if (areAllEqual(row, column, n)) {
            node.isLeaf = true;
            node.val = grid[row][column] == 1;
        } else {
            n /= 2;
            node.isLeaf = false;
            node.val = false;

            node.topLeft = dfs(row, column, n);
            node.bottomLeft = dfs(row + n, column, n);
            node.topRight = dfs(row, column + n, n);
            node.bottomRight = dfs(row + n, column + n, n);
        }

        return node;
    }

    private boolean areAllEqual(int row, int column, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[row][column] != grid[row + i][column + j]) {
                    return false;
                }
            }
        }

        return true;
    }

}

public class Solution {

    public int eraseOverlapIntervals(int[][] intervals) {
        int intervalsRemoved = 0;

        Arrays.sort(
            intervals,
            (arr1, arr2) -> Integer.compare(arr1[0], arr2[0])
        );

        int[] intervalFirst = intervals[0];

        for (int i = 1; i < intervals.length; i++) {
            if (firstIntervalwithinSecond(intervalFirst, intervals[i])) {
                //mark first interval to be removed
                intervalsRemoved++;
                // determine which interval to remove
                //remove the interval that ends last
                if (intervalFirst[1] > intervals[i][1]) {
                    intervalFirst = intervals[i];
                }
            } else {
                intervalFirst = intervals[i];
            }
        }
        return intervalsRemoved;
    }

    public boolean firstIntervalwithinSecond(
        int[] intervalFirst,
        int[] intervalSecond
    ) {
        return intervalSecond[0] < intervalFirst[1];
    }
}

class Solution {
    public List<Integer> findAnagrams(String s, String p) {
        int startIndex = 0;
        Map<Character, Integer> pMap = new HashMap<>(), sMap = new HashMap<>();
        List<Integer> res = new ArrayList<>();

        for(char c: p.toCharArray())
            pMap.put(c, 1 + pMap.getOrDefault(c, 0));

        for(int i = 0; i < s.length(); i++) {
            sMap.put(s.charAt(i), 1 + sMap.getOrDefault(s.charAt(i), 0));

            if(i >= p.length() - 1) {
                if(sMap.equals(pMap))
                    res.add(startIndex);

                //if current character is in sMap, remove it and re-update the map.
                if(sMap.containsKey(s.charAt(startIndex))) {
                    sMap.put(s.charAt(startIndex), sMap.get(s.charAt(startIndex)) - 1);
                    if(sMap.get(s.charAt(startIndex)) == 0)
                        sMap.remove(s.charAt(startIndex));
                }
                startIndex += 1;
            }
        }

        return res;
    }
}

class Solution {
    public int arrangeCoins(int n) {

        int completedRows = 0;
        long left = 1;
        long right = n;
        while (left <= right) {

            int mid = (int) ((left + right) / 2);
            long coins = (long) ((mid / 2.0) * (mid + 1));
            if (coins > n) {
                right = mid - 1;
            } else {
                completedRows = Math.max(completedRows, mid);
                left = mid + 1;
            }

        }

        return completedRows;
    }
}

