        var res = points.length;
        var prev = points[0];
        for (int i = 1; i < points.length; i++) {
            int[] curr = points[i];
            if (curr[0] <= prev[1]) {
                res--;
                prev[0] = curr[0];
                prev[1] = Math.min(curr[1], prev[1]);
            } else {
                prev = curr;
            }
        }

        return res;
    }
}

class Solution {
    public int findContentChildren(int[] g, int[] s) {
        Arrays.sort(g);
        Arrays.sort(s);

        int i = 0, j = 0;
        while(i < g.length){
            while(j < s.length && g[i] > s[j])
                j += 1;
            if(j == s.length)
                break;
            i += 1;
            j += 1;
        }
        return i;
    }
}

class Solution {
    /*
     * Mono Stack
     * TC: O(n)
     * SC: O(n)
     */
    public boolean find132pattern(int[] nums) {
        int n = nums.length;
        Stack<Integer> st = new Stack<>();
        int secondMax = Integer.MIN_VALUE;

        for (int x = n - 1; x >= 0; x--) {
            if (nums[x] < secondMax)
                return true;

            while (!st.isEmpty() && st.peek() < nums[x])
                secondMax = Math.max(st.pop(), secondMax);

            st.push(nums[x]);
        }
        return false;
    }
}

class LFUCache {
    private static class Entry {
        int key;
        int value;
        int freq;

        public Entry(int key, int value, int freq) {
            this.key = key;
            this.value = value;
            this.freq = freq;
        }
    }

    private final int capacity;
    private int minFreq = 0;
    private final Map<Integer, Entry> entries = new HashMap<>();
    private final Map<Integer, LinkedHashSet<Entry>> freqMap = new HashMap<>();

    public LFUCache(int capacity) {
        this.capacity = capacity;
    }

    public int get(int key) {
        Entry e = entries.get(key);
        if (e == null) return -1;
        updateFrequency(e);
        return e.value;
    }

    public void put(int key, int value) {
        if (capacity == 0) return;
        if (entries.containsKey(key)) {
            Entry e = entries.get(key);
            e.value = value;
            updateFrequency(e);
        } else {
            if (entries.size() == capacity) {
                evictLeastFrequent();
            }
            Entry e = new Entry(key, value, 1);
            entries.put(key, e);
            freqMap.computeIfAbsent(1, k -> new LinkedHashSet<>()).add(e);
            minFreq = 1; // Reset min frequency to 1 for new entry
        }
    }

    private void updateFrequency(Entry e) {
        int oldFreq = e.freq;
        int newFreq = oldFreq + 1;

        freqMap.get(oldFreq).remove(e);
        if (freqMap.get(oldFreq).isEmpty()) {
            freqMap.remove(oldFreq);
            if (minFreq == oldFreq) minFreq++;
        }

        e.freq = newFreq;
        freqMap.computeIfAbsent(newFreq, k -> new LinkedHashSet<>()).add(e);
    }

    private void evictLeastFrequent() {
        LinkedHashSet<Entry> minFreqEntries = freqMap.get(minFreq);
        Entry toRemove = minFreqEntries.iterator().next();
        minFreqEntries.remove(toRemove);
        if (minFreqEntries.isEmpty()) {
            freqMap.remove(minFreq);
        }

        entries.remove(toRemove.key);
    }
}

class Solution {
    class RecursiveBiFunction<A, B, C> {
        BiFunction<A, B, C> func;
    }

    public int islandPerimeter(int[][] _grid) {
        final int[][] grid = _grid;
        final Set<Integer> visit = new HashSet<>();

        final RecursiveBiFunction<Integer, Integer, Integer> dfs = new RecursiveBiFunction();
        dfs.func = (i, j) -> {
            if(i >= grid.length || j >= grid[0].length || i < 0 || j < 0 || grid[i][j] == 0)
                return 1;
            //convert 2D-Coordinate to 1D-Coordinate
            int flatCoord = i*grid[0].length + j;
            if(visit.contains(flatCoord))
                return 0;

            visit.add(flatCoord);
            int perim = dfs.func.apply(i, j + 1);
            perim += dfs.func.apply(i + 1, j);
            perim += dfs.func.apply(i, j - 1);
            perim += dfs.func.apply(i - 1, j);
            return perim;
        };

        for(int i = 0; i < grid.length; i++)
            for(int j = 0; j < grid[0].length; j++)
                if(grid[i][j] != 0)
                    return dfs.func.apply(i, j);
        return -1;
    }
}

class Solution {
    boolean[] used;
    public boolean makesquare(int[] matchsticks) {
        used = new boolean[matchsticks.length];
        int total = 0;
        for (int n : matchsticks) {
            total += n;
        }
        //Check if total of all the sides is divisible by 4 or not
        if (total % 4 != 0) return false;
        int side = total / 4;

        return helper(matchsticks, side, 0, 0, 4);
    }

    boolean helper(int[] matchsticks, int targetSide, int currentSum, int index, int sides) {
        //if all the sides are matching the target side length then we found a solution
        if (sides == 0)
            return true;
        //Check if current side is equal to targetSide , that means we found another side
        if (currentSum == targetSide) {
            return helper(matchsticks, targetSide, 0, 0, sides - 1);
        }

        for (int i = index; i < matchsticks.length; i++) {
            //Only use matchsticks which are not used and which doesn't increase the current side more than target side
            if (!used[i] && currentSum + matchsticks[i] <= targetSide) {
                used[i] = true;
                boolean found = helper(matchsticks, targetSide, currentSum + matchsticks[i], i + 1, sides);
                if (found) {
                    return true;
                }
                used[i] = false;
            }
        }
        return false;
    }


}

class Solution {
    public int findMaxForm(String[] strs, int m, int n) {
        int[][] dp = new int[m + 1][n + 1];
        for (String str : strs) {
            int zeros = (int) str.chars().filter(ch -> ch == '0').count();
            int ones = (int) str.chars().filter(ch -> ch == '1').count();
            for (int i = m; i >= zeros; i--) {
                for (int j = n; j >= ones; j--) {
                    dp[i][j] = Math.max(dp[i][j], dp[i - zeros][j - ones] + 1);
                }
            }
        }
        return dp[m][n];
    }
}

