class Solution {
    /**
     * BFS Solution with Runtime Complexity O(n) -> O(n log n)
     */
    public int[] findMode(TreeNode root) {
        if (root == null) return new int[0];
        List<Integer> curr = new ArrayList<>();
        Map<Integer, Integer> freqMap = new HashMap<>();
        Queue<TreeNode> q = new ArrayDeque<>();
        q.offer(root);

        while (!q.isEmpty()) {
            int n = q.size();
            for (int i = 0; i < n; i++) {
                TreeNode node = q.poll();
                if (freqMap.containsKey(node.val))
                    freqMap.put(node.val, freqMap.get(node.val) + 1);
                else
                    freqMap.put(node.val, 1);

                if (node.left != null) q.offer(node.left);
                if (node.right != null) q.offer(node.right);
            }
        }

        int currMax = 0;
        for (Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
            int key = entry.getKey();
            int value = entry.getValue();

            if (value > currMax) {
                curr.clear();
                curr.add(key);
                currMax = Math.max(currMax, value);
            } else if (value == currMax){
                curr.add(key);
            }
        }

        int[] res = new int[curr.size()];
        for (int j = 0; j < curr.size(); j++) {
            res[j] = curr.get(j);
        }
        return res;
    }
}

class Solution {
    public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        // Max-heap for profits of affordable projects
        Queue<Integer> maxProfit = new PriorityQueue<>(Comparator.reverseOrder());

        // Min-heap for (capital, profit) pairs
        Queue<int[]> minCapital = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));

        for (int i = 0; i < capital.length; i++) {
            minCapital.add(new int[] { capital[i], profits[i] });
        }

        for (int i = 0; i < k; i++) {
            // Add all affordable projects to the maxProfit heap
            while (!minCapital.isEmpty() && minCapital.peek()[0] <= w) {
                int[] project = minCapital.poll();
                maxProfit.add(project[1]);
            }

            // If there are no affordable projects, break
            if (maxProfit.isEmpty()) {
                break;
            }

            // Select the project with the maximum profit
            w += maxProfit.poll();
        }

        return w;
    }
}

class Solution {

    static class pair {
        TreeNode node;
        int level;
        pair(TreeNode node, int level) {
            this.node = node;
            this.level = level;
        }
    }

    public static int findBottomLeftValue(TreeNode root) {
        Queue<pair> q = new ArrayDeque<>();
        q.add(new pair(root, 0));
        pair ans = new pair(root, 0);
        while (!q.isEmpty()) {
            pair current = q.poll();
            TreeNode currentNode = current.node;
            int currentLevel = current.level;
            if (currentNode.left != null) q.add(new pair(currentNode.left, currentLevel + 1));
            if (currentNode.right != null) q.add(new pair(currentNode.right, currentLevel + 1));
            if (ans.level < currentLevel) ans = current;
        }
        return ans.node.val;
    }
}

class Solution {
    Map<String, Integer> cache = new HashMap<>();

    public int findRotateSteps(String ring, String key) {
        return helper(ring, key, 0, 0);
    }

    private int helper(String ring, String key, int r, int k) {
        if (k == key.length())
            return 0;
        String keyCache = r + "," + k;
        if (cache.containsKey(keyCache))
            return cache.get(keyCache);

        int res = Integer.MAX_VALUE;
        for (int i = 0; i < ring.length(); i++) {
            if (ring.charAt(i) == key.charAt(k)) {
                int minDist = Math.min(Math.abs(r - i), ring.length() - Math.abs(r - i));
                int steps = minDist + 1 + helper(ring, key, i, k + 1);
                res = Math.min(res, steps);
            }
        }

        cache.put(keyCache, res);
        return res;
    }
}

// Dynammic Programming - Tabulation
// Time Complexity (n * amount) | Space Complexity (amount) where n is the length of coins
class Solution {

    public int change(int amount, int[] coins) {
        int[] dp = new int[amount + 1];

        // if amount is 0, there is only 1 way of making change (no money)
        dp[0] = 1;

        for (int coin : coins) {
            for (int i = 1; i <= amount; i++) {
                if (coin <= i) {
                    dp[i] += dp[i - coin];
                }
            }
        }

        return dp[amount];
    }
}

//We are basically storing sum%k and storing it in the hashmap and checking it.
//Math logic is that the overall sum will get cancelled out because of modulo

class Solution {
    public boolean checkSubarraySum(int[] nums, int k) {
        HashMap<Integer, Integer> map = new HashMap<>();
        map.put(0, -1);
        int sum = 0;
        for (int i = 0; i<nums.length; i++) {
            sum += nums[i];
            int rem = sum%k;
            if (map.containsKey(rem))
                if (i - map.get(rem)>=2)
                    return true;
            if (!map.containsKey(rem))
                map.put(rem, i);
        }
        return false;
    }
}

class Solution {
    public int findMaxLength(int[] nums) {
        int zero = 0;
        int one = 0;
        int res = 0;

        HashMap<Integer, Integer> diffIndex = new HashMap<>();

        for (int i = 0; i < nums.length; i++) {
            int n = nums[i];
            if (n == 0)
                zero++;
            else
                one++;
            if (diffIndex.get(one - zero) == null)
                diffIndex.put(one - zero, i);

            if (one == zero) {
                res = one + zero;
            } else {
                int idx = diffIndex.getOrDefault(one - zero, 0);
                res = Math.max(res, i - idx);
            }
        }

        return res;
    }
}

