class Solution {

    public TreeNode mergeTrees(TreeNode root1, TreeNode root2) {
        if (root1 == null && root2 == null) return null;

        int val1 = root1 != null ? root1.val : 0;
        int val2 = root2 != null ? root2.val : 0;

        TreeNode root = new TreeNode(val1 + val2);

        // merge left side of trees if they are not null
        root.left =
            mergeTrees(
                (root1 != null && root1.left != null) ? root1.left : null,
                (root2 != null && root2.left != null) ? root2.left : null
            );

        // merge righ side of trees if they are not null
        root.right =
            mergeTrees(
                (root1 != null && root1.right != null) ? root1.right : null,
                (root2 != null && root2.right != null) ? root2.right : null
            );

        return root;
    }
}

class Solution {

    public int leastInterval(char[] tasks, int n) {
        if (n == 0) return tasks.length;
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        Queue<Pair<Integer, Integer>> q = new LinkedList<>();
        int[] arr = new int[26];
        for (char c : tasks) arr[c - 'A']++;
        for (int val : arr) if (val > 0) pq.add(val);
        int time = 0;

        while ((!pq.isEmpty() || !q.isEmpty())) {
            time++;
            if (!pq.isEmpty()) {
                int val = pq.poll();
                val--;
                if (val > 0) q.add(new Pair(val, time + n));
            }

            if (!q.isEmpty() && q.peek().getValue() == time) pq.add(
                q.poll().getKey()
            );
        }
        return time;
    }
}

class MyCircularQueue {
    Node head=null;
    Node tail=null;

    int currentLength=0;
    int totalLength=0;
    public MyCircularQueue(int k) {
        head=new Node(-1);
        tail=new Node(-1);

        head.next=tail;
        head.prev=tail;

        tail.next=head;
        tail.prev =head;

        totalLength=k;
    }

    public boolean enQueue(int value) {
        if(isFull()){
            return false;
        }

        Node left = head.prev;
        Node right= head;

        Node temp = new Node(value);

        temp.next= right;

        right.prev = temp;

        left.next=temp;

        temp.prev=left;

        currentLength++;



        return true;
    }

    public boolean deQueue() {
        if(isEmpty()){
            return false;
        }

        Node left = tail;
        Node right= tail.next.next;

       left.next = right;

       right.prev = left;


        currentLength--;

        return true;
    }

    public int Front() {
        if(currentLength<=0){
            return -1;
        }

        return tail.next.val;
    }

    public int Rear() {
        if(currentLength<=0){
            return -1;
        }

        return head.prev.val;
    }

    public boolean isEmpty() {
        return currentLength==0 ? true : false;
    }

    public boolean isFull() {
        return currentLength==totalLength ? true : false;
    }

}

