class Solution {
    public int[][] imageSmoother(int[][] img) {
        int ROWS = img.length, COLS = img[0].length;

        for(int r = 0; r < ROWS; r++){
            for(int c = 0; c < COLS; c++){
                int total = 0, cnt = 0;

                for(int i = r - 1; i < r + 2; i++){
                    for(int j = c - 1; j < c + 2; j++){
                        if(i < 0 || i == ROWS || j < 0 || j == COLS)
                            continue;
                        total += img[i][j] % 256;
                        cnt += 1;
                    }
                }
                img[r][c] = img[r][c] ^ (total / cnt) << 8;
            }
        }
        for(int r = 0; r < ROWS; r++){
            for(int c = 0; c < COLS; c++){
                img[r][c] = img[r][c] >> 8;
            }
        }
        return img;
    }
}

class Solution {
    public int widthOfBinaryTree(TreeNode root) {
        int res = 0;
        Queue<tuple> q = new LinkedList<>();
        q.add(new tuple(root, 1, 0));
        int prevLevel = 0, prevNum = 1;

        while(!q.isEmpty()){
            tuple curr = q.poll();
            TreeNode node = curr.node;
            int num = curr.num, level = curr.level;

            if(level > prevLevel){
                prevLevel = level;
                prevNum = num;
            }
            res = Math.max(res, num - prevNum + 1);
            if(node.left != null)
                q.add(new tuple(node.left, num*2, level + 1));
            if(node.right != null)
                q.add(new tuple(node.right, num*2 + 1, level + 1));
        }
        return res;
    }
}
