class Solution {
    public int maximumSwap(int num) {
        StringBuilder str = new StringBuilder(Integer.toString(num));
        if(str.length() == 1){
            return num;
        }

        int[] maxRight = new int[str.length()];
        int max = str.length()-1;
        for(int i = str.length()-1; i >= 0; i--){
            maxRight[i] = max;
            if(str.charAt(i) > str.charAt(max)){
                max = i;
            }
        }

        for(int i = 0; i < str.length(); i++){
            if(str.charAt(maxRight[i]) > str.charAt(i)){
                char t = str.charAt(maxRight[i]);
                str.setCharAt(maxRight[i], str.charAt(i));
                str.setCharAt(i, t);
                break;
            }
        }

        return Integer.parseInt(str.toString());
    }
}

class Solution {
    public int findNumberOfLIS(int[] nums) {
        int[][] dp = new int[nums.length][2];
        int LISLength = 0;
        int LISCount = 0;
        for (int i = nums.length - 1; i >= 0; i--) {
            int maxLength = 1;
            int maxCount = 1;
            for (int j = i + 1; j < nums.length; j++) {
                if (nums[j] > nums[i]) {
                    int length = dp[j][0];
                    int count = dp[j][1];
                    if (length + 1 > maxLength) {
                        maxLength = length + 1;
                        maxCount = count;
                    } else if (length + 1 == maxLength) {
                        maxCount += count;
                    }
                }
            }
            if (maxLength > LISLength) {
                LISLength = maxLength;
                LISCount = maxCount;
            } else if (maxLength == LISLength) {
                LISCount += maxCount;
            }
            dp[i] = new int[] { maxLength, maxCount };
        }
        return LISCount;
    }
}

class Solution {

    public boolean checkValidString(String s) {
        int count = 0;
        Stack<Integer> op = new Stack<>();
        Stack<Integer> st = new Stack<>();

        for (int i = 0; i < s.length(); ++i) {
            if (s.charAt(i) == '(') op.push(i); // index of opening
            else if (s.charAt(i) == ')') {
                if (op.size() > 0) op.pop(); // if we have brackets
                else if (st.size() > 0) st.pop(); // if not brackets do we have stars
                else return false; // a closing bracket without opening and star
            } else st.push(i); // index of star
        }
        // if we left with some opening bracket that over stars con cover up
        while (op.size() > 0 && st.size() > 0) {
            if (op.peek() > st.peek()) return false;
            op.pop();
            st.pop();
        }

        return op.size() == 0;
    }
}

