class DSU {
    int[] parent;
    int[] rank;

    public DSU(int size) {
        rank = new int[size];
        parent = new int[size];
        for (int i = 0; i < size; i++)
            parent[i] = i;
    }

    public int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    // Union By Rank

    public boolean union(int x, int y) {
        int xr = find(x), yr = find(y);
        if (xr == yr) {
            return false;
        } else if (rank[xr] < rank[yr]) {
            parent[xr] = yr;
        } else if (rank[xr] > rank[yr]) {
            parent[yr] = xr;
        } else {
            parent[yr] = xr;
            rank[xr]++;
        }
        return true;
    }
}

class Solution {
    public int pivotIndex(int[] nums) {
        int totalSum = 0;
        for (int i = 0; i < nums.length; i++) {
            totalSum += nums[i];
        }
        int leftSum = 0;
        for (int i = 0; i < nums.length; i++) {
            int rightSum = totalSum - leftSum - nums[i];
            if (leftSum == rightSum) {
                return i;
            }
            leftSum += nums[i];
        }
        return -1;
    }
}

class Solution {
    public ListNode[] splitListToParts(ListNode head, int k) {
        int numNodes = countNodes(head);
        ListNode[] ans = new ListNode[k];

        int remainder = numNodes % k;
        int base_len = numNodes / k;
        ListNode curr = head;

        for (int i = 0; i < k; i++) {
            ListNode dummy = new ListNode(0), currHead = dummy;
            for (int j = 0; j < base_len + (i < remainder ? 1 : 0); j++) {
                currHead = currHead.next = new ListNode(curr.val);
                if (curr != null) curr = curr.next;
            }
            ans[i] = dummy.next;
        }
        return ans;
    }

    private int countNodes(ListNode root) {
        int cnt = 0;
        while (root != null) {
            cnt++;
            root = root.next;
        }
        return cnt;
    }
}

