class MyCalendarTwo {

    List<int[]> non_overlapping;
    List<int[]> overlapping;

    public MyCalendarTwo() {
        non_overlapping = new ArrayList<>();
        overlapping = new ArrayList<>();
    }

    public boolean book(int start, int end) {
        for(int[] arr: overlapping){
            int s = arr[0], e = arr[1];
            if(start < e && end > s){
                return false;
            }
        }

        for(int[] arr: non_overlapping){
            int s = arr[0], e = arr[1];
            if(start < e && end > s){
                overlapping.add(new int[]{Math.max(start, s), Math.min(end, e)});
            }
        }
        non_overlapping.add(new int[]{start, end});
        return true;
    }
}

class Solution {
    public int[] asteroidCollision(int[] asteroids) {
        Stack<Integer> stack = new Stack<>();
        int index = 0;

        while(index < asteroids.length) {
            int a = asteroids[index];
            if(stack.isEmpty()) {
                stack.push(a);
                index++;
            } else {
                if(stack.peek() > 0 && a < 0) {
                    if(Math.abs(stack.peek()) > Math.abs(a)) {
                        index++;
                    } else if(Math.abs(stack.peek()) < Math.abs(a)) {
                        stack.pop();
                    } else {
                        index++;
                        stack.pop();
                    }
                } else {
                    stack.push(a);
                    index++;
                }
            }
        }

        int[] res = new int[stack.size()];
        for(int i=res.length-1; i>=0 ;i--) {
            res[i] = stack.pop();
        }
        return res;
    }
}

class Solution {

    public int[] dailyTemperatures(int[] temperatures) {
        int[] ans = new int[temperatures.length];
        Stack<Integer> stack = new Stack<>();
        for (int currDay = 0; currDay < temperatures.length; currDay++) {
            while (
                !stack.isEmpty() &&
                temperatures[currDay] > temperatures[stack.peek()]
            ) {
                int prevDay = stack.pop();
                ans[prevDay] = currDay - prevDay;
            }
            stack.add(currDay);
        }
        return ans;
    }
}

class Solution {
    public int deleteAndEarn(int[] nums) {
        Map<Integer, Integer> counter = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            counter.put(nums[i], counter.getOrDefault(nums[i], 0) + 1);
        }
        List<Integer> numsList = new ArrayList<>(counter.keySet());
        Collections.sort(numsList);

        int earnOne = 0;
        int earnTwo = 0;
        for (int i = 0; i < numsList.size(); i++) {
            int curEarn = numsList.get(i) * counter.get(numsList.get(i));
            if (i > 0 && numsList.get(i) == numsList.get(i - 1) + 1) {
                int temp = earnTwo;
                earnTwo = Math.max(earnOne + curEarn, earnTwo);
                earnOne = temp;
            } else {
                earnOne = earnTwo;
                earnTwo += curEarn;
            }
        }
        return earnTwo;
    }
}

// Bellman Ford ALgorithm
// Time Complexty (n * t) | Space Complexity O(n) where t is the length of times
class Solution {

    public int networkDelayTime(int[][] times, int n, int k) {
        // initialize an array with max value of size n
        int[] paths = new int[n];
        Arrays.fill(paths, Integer.MAX_VALUE);

        paths[k - 1] = 0;

        for (int i = 0; i < n; i++) {
            // make a copy of paths
            int[] temp = new int[n];
            temp = Arrays.copyOf(paths, paths.length);

            // loop through times
            for (int j = 0; j < times.length; j++) {
                int src = times[j][0]; // source
                int tgt = times[j][1]; // target
                int time = times[j][2]; // time

                if (
                    temp[src - 1] != Integer.MAX_VALUE &&
                    temp[src - 1] + time < temp[tgt - 1]
                ) {
                    temp[tgt - 1] = temp[src - 1] + time;
                }
            }

            // set paths to temp
            paths = temp;
        }

        int result = Integer.MIN_VALUE;

        // calculate max value
        for (int i = 0; i < n; i++) {
            if (paths[i] == Integer.MAX_VALUE) {
                return -1;
            }
            result = Math.max(result, paths[i]);
        }

        // return result
        return result;
    }
}

class Solution {
    public int minCostClimbingStairs(int[] cost) {
        int one = 0;
        int two = 0;

        for (int i = cost.length - 1; i >= 0; i--) {
            cost[i] += Math.min(one, two);
            two = one;
            one = cost[i];
        }

        return Math.min(cost[0], cost[1]);
    }
}

class Solution {
    public int openLock(String[] deadends, String target) {
        Set<String> visited = new HashSet<>();
        for (String deadend : deadends) {
            if (deadend.equals("0000")) {
                return -1;
            }
            visited.add(deadend);
        }

        Queue<String> queue = new LinkedList<>();
        queue.offer("0000");
        visited.add("0000");

        int turns = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String lock = queue.poll();
                if (lock.equals(target)) {
                    return turns;
                }
                List<String> children = generateChildren(lock);
                for (String child : children) {
                    if (!visited.contains(child)) {
                        visited.add(child);
                        queue.offer(child);
                    }
                }
            }
            turns++;
        }
        return -1;
    }

    private List<String> generateChildren(String lock) {
        List<String> children = new ArrayList<>();
        for (int i = 0; i < 4; i++) {
            char[] digits = lock.toCharArray();
            digits[i] = (char)(((digits[i] - '0' + 1) % 10) + '0');
            children.add(new String(digits));
            digits[i] = (char)(((digits[i] - '0' - 2 + 10) % 10) + '0');
            children.add(new String(digits));
        }
        return children;
    }
}

class Solution {

    public List<Integer> partitionLabels(String s) {
        List<Integer> list = new ArrayList<>();
        HashMap<Character, Integer> map = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            map.put(s.charAt(i), i);
        }
        int j = 0;
        int i = 0;
        while (i < s.length()) {
            int count = 0;
            j = Math.max(j, map.get(s.charAt(i)));
            while (i <= j) {
                j = Math.max(j, map.get(s.charAt(i)));
                i++;
                count++;
            }
            list.add(count);
        }
        return list;
    }
}

//See this comment for explanation https://leetcode.com/problems/reorganize-string/discuss/113440/Java-solution-PriorityQueue/211009

class Solution {

    public String reorganizeString(String s) {
        HashMap<Character, Integer> map = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            map.put(s.charAt(i), map.getOrDefault(s.charAt(i), 0) + 1);
        }
        PriorityQueue<Map.Entry<Character, Integer>> pq = new PriorityQueue<>(
                (a, b) ->
            b.getValue() - a.getValue()
        );
        pq.addAll(map.entrySet());

        StringBuilder sb = new StringBuilder();

        while (!pq.isEmpty()) {
            Map.Entry<Character, Integer> temp1 = pq.poll();
            //if the character at sb's end is different from the max frequency character or the string is empty
            if (
                sb.length() == 0 || sb.charAt(sb.length() - 1) != temp1.getKey()
            ) {
                sb.append(temp1.getKey());
                //update the value
                temp1.setValue(temp1.getValue() - 1);
            } else { //the character is same
                //hold the current character and look for the 2nd most frequent character
                Map.Entry<Character, Integer> temp2 = pq.poll();
                //if there is no temp2 i.e. the temp1 was the only character in the heap then there is no way to avoid adjacent duplicate values
                if (temp2 == null) return "";
                //else do the same thing as above
                sb.append(temp2.getKey());
                //update the value
                temp2.setValue(temp2.getValue() - 1);
                //if still has some value left add again to the heap
                if (temp2.getValue() != 0) pq.offer(temp2);
            }
            if (temp1.getValue() != 0) pq.offer(temp1);
        }
        return sb.toString();
    }
}

// Solution: Greedy Approach with Min Heap
// Time Complexity: O((n^2)*log(n))
class Solution {

    private int[][] dirs = { { -1, 0 }, { 1, 0 }, { 0, -1 }, { 0, 1 } };

    public int swimInWater(int[][] grid) {
        int len = grid.length;

        if (len == 1) {
            return 0;
        }

        var seen = new boolean[len][len];
        seen[0][0] = true;

        var minHeap = new PriorityQueue<Integer[]>((a, b) -> a[0] - b[0]);
        minHeap.add(new Integer[] { grid[0][0], 0, 0 });

        int result = 0;

        while (!minHeap.isEmpty()) {
            var curr = minHeap.poll();

            result = Math.max(result, curr[0]);

            if (curr[1] == len - 1 && curr[2] == len - 1) {
                break;
            }

            for (int i = 0; i < 4; i++) {
                int x = curr[1] + dirs[i][0];
                int y = curr[2] + dirs[i][1];

                if (x < 0 || x >= len || y < 0 || y >= len || seen[x][y]) {
                    continue;
                }

                minHeap.add(new Integer[] { grid[x][y], x, y });
                seen[x][y] = true;
            }
        }

        return result;
    }
}

class Solution {
    public int kthGrammar(int n, int k) {
        int left = 1;
        int right = (int)Math.pow(2,n-1);
        int cur = 0;

        for(int i = 0; i < n-1; i++){
            int mid = (left + right)/2;
            if(k <= mid)
                right = mid;
            else{
                left = mid + 1;
                cur = (cur == 1)? 0: 1;
            }
        }
        return cur;
    }
}

