        }
    }
}

class Solution {
    public double champagneTower(int poured, int query_row, int query_glass) {
        double[] prev_row = {poured};

        for(int row = 1; row < query_row+1; row++){
            double[] cur_row = new double[row+1];
            for(int i = 0; i < row; i++){
                double extra = prev_row[i] - 1;
                if(extra > 0){
                    cur_row[i] += 0.5 * extra;
                    cur_row[i+1] += 0.5 * extra;
                }
            }
            prev_row = cur_row;
        }
        return Math.min(1, prev_row[query_glass]);
    }
}

class Solution {
    public List<Integer> eventualSafeNodes(int[][] graph) {
        List<Integer> res = new ArrayList<>();
        HashMap<Integer, Boolean> safe = new HashMap<>();
        for(int i = 0; i < graph.length; i++){
            if(dfs(graph, i, safe))
                res.add(i);
        }
        return res;
    }

    private boolean dfs(int[][] graph, int src, HashMap<Integer, Boolean> safe) {
        if (safe.containsKey(src))
            return safe.get(src);

        safe.put(src, false);

        for (int neighbour : graph[src]) {
            if (!dfs(graph, neighbour, safe))
                    return false;
        }
        safe.put(src, true);
        return true;
    }
}

class Solution {
    public double new21Game(int n, int k, int maxPts) {
        if (k == 0) {
            return 1.0;
        }

        double windowSum = 0.0;
        for (int i = k; i < k + maxPts; i++) {
            windowSum += (i <= n) ? 1.0 : 0.0;
        }

        Map<Integer, Double> dp = new HashMap<>();
        for (int i = k - 1; i >= 0; i--) {
            dp.put(i, windowSum / maxPts);
            double remove = 0.0;
            if (i + maxPts <= n) {
                remove = dp.getOrDefault(i + maxPts, 1.0);
            }
            windowSum += (dp.get(i) - remove);
        }

        return dp.get(0);
    }
}

class Solution {
    public String pushDominoes(String dominoes) {
        int len = dominoes.length();
        Queue<Integer> q = new LinkedList<>();
        char[] dom = dominoes.toCharArray();
        for (int i = 0; i < len; i++)
            if (dominoes.charAt(i) != '.') q.offer(i);

        while (!q.isEmpty()) {
            int i = q.poll();
            char ch = dom[i];
            if (dom[i] == 'R') {
                if (i + 1 < len && dom[i + 1] == '.') {
                    if (i + 2 < len && dom[i + 2] == 'L') {
                        q.poll();
                    } else {
                        dom[i + 1] = 'R';
                        q.offer(i + 1);
                    }
                }
            } else if (i > 0 && dom[i - 1] == '.') {
                dom[i - 1] = 'L';
                q.offer(i - 1);
            }
        }
        return String.valueOf(dom);
    }
}

class Solution {

    public boolean isNStraightHand(int[] hand, int groupSize) {
        if (hand.length % groupSize != 0) return false;

        HashMap<Integer, Integer> hm = new HashMap<>();
        for (int card : hand) hm.put(card, hm.getOrDefault(card, 0) + 1);

        Arrays.sort(hand);
        for (int card : hand) {
            if (hm.get(card) <= 0) continue;
            for (int i = 1; i < groupSize; i++) {
                int count = hm.getOrDefault(card + i, 0);
                if (count > 0) hm.put(card + i, count - 1); else return false;
            }
            hm.put(card, hm.get(card) - 1);
        }

        return true;
    }
}

class Solution {

    public int peakIndexInMountainArray(int[] arr) {
        int left = 0, right = arr.length - 1;
        int res = -1;

        while (left <= right) {
            int mid = left + (right - left + 1) / 2;

            if (arr[mid - 1] <= arr[mid]) {
                left = mid + 1;
                res = mid;
            } else {
                right = mid - 1;
            }
        }

        return res;
    }
}

class Solution {

    public int carFleet(int target, int[] position, int[] speed) {
        if (position.length == 1) return 1;
        Stack<Double> stack = new Stack<>();
        int[][] combine = new int[position.length][2];
        for (int i = 0; i < position.length; i++) {
            combine[i][0] = position[i];
            combine[i][1] = speed[i];
        }

        Arrays.sort(combine, java.util.Comparator.comparingInt(o -> o[0]));
        for (int i = combine.length - 1; i >= 0; i--) {
            double currentTime = (double) (target - combine[i][0]) /
            combine[i][1];
            if (!stack.isEmpty() && currentTime <= stack.peek()) {
                continue;
            } else {
                stack.push(currentTime);
            }
        }
        return stack.size();
    }
}

//Just store the value for parent values of the nodes in a map and just do bfs as we do in graph.

class Solution {

    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        HashMap<TreeNode, TreeNode> map = new HashMap<>();
        //First bfs to make a mapping to the parent nodes
        Queue<TreeNode> q1 = new LinkedList<>();
        q1.offer(root);
        while (!q1.isEmpty()) {
            int size = q1.size();
            for (int i = 0; i < size; i++) {
                TreeNode cur = q1.poll();
                if (cur.left != null) {
                    q1.offer(cur.left);
                    map.put(cur.left, cur);
                }
                if (cur.right != null) {
                    q1.offer(cur.right);
                    map.put(cur.right, cur);
                }
            }
        }
        //Now do the bfs
        //Same as we do in graphs with a visited set
        Queue<TreeNode> q2 = new LinkedList<>();
        HashSet<TreeNode> vis = new HashSet<>();
        List<Integer> ans = new ArrayList<>();
        int dis = 0;
        q2.offer(target);
        while (!q2.isEmpty()) {
            int size = q2.size();
            for (int i = 0; i < size; i++) {
                TreeNode cur = q2.poll();
                if (!vis.contains(cur)) {
                    if (cur.left != null) q2.offer(cur.left);
                    if (cur.right != null) q2.offer(cur.right);
                    if (map.get(cur) != null) q2.offer(map.get(cur));
                    if (dis == k) {
                        ans.add(cur.val);
                    }
                }
                vis.add(cur);
            }
            dis++;
        }
        return ans;
    }
}

class Solution {
