class Solution {
    HashMap<Integer, List<TreeNode>> memo = new HashMap<>();
    public List<TreeNode> allPossibleFBT(int n) {
        if(n == 0)
            return new ArrayList<TreeNode>();
        if(n == 1)
            return new ArrayList<TreeNode>(Arrays.asList(new TreeNode(0)));
        if(memo.containsKey(n))
            return memo.get(n);

        List<TreeNode> res = new ArrayList<>();
        for(int l = 0; l < n; l++){
            int r = n-1-l;
            List<TreeNode> leftTree = allPossibleFBT(l);
            List<TreeNode> rightTree = allPossibleFBT(r);

            for(TreeNode t1 : leftTree){
                for(TreeNode t2 : rightTree){
                    res.add(new TreeNode(0, t1, t2));
                }
            }
        }
        memo.put(n, res);
        return res;
    }
}

class FreqStack {
    HashMap<Integer, Integer> freq = new HashMap<>();
    HashMap<Integer, Stack<Integer>> m = new HashMap<>();
    int maxfreq = 0;

    public void push(int x) {
        int f = freq.getOrDefault(x, 0) + 1;
        freq.put(x, f);
        maxfreq = Math.max(maxfreq, f);
        if (!m.containsKey(f)) m.put(f, new Stack<Integer>());
        m.get(f).add(x);
    }

    public int pop() {
        int x = m.get(maxfreq).pop();
        freq.put(x, maxfreq - 1);
        if (m.get(maxfreq).size() == 0) maxfreq--;
        return x;
    }
}

