class Solution {
    public int sumSubarrayMins(int[] arr) {
        int MOD = 1000000007;
        int res = 0;
        int[] extendedArr = new int[arr.length + 2];

        for (int i = 0; i < arr.length; i++) {
            extendedArr[i + 1] = arr[i];
        }
        extendedArr[0] = Integer.MIN_VALUE;
        extendedArr[extendedArr.length - 1] = Integer.MIN_VALUE;

        Stack<int[]> stack = new Stack<>(); // (index, num)

        for (int i = 0; i < extendedArr.length; i++) {
            while (!stack.isEmpty() && extendedArr[i] < stack.peek()[1]) {
                int[] popped = stack.pop();
                int j = popped[0];
                int m = popped[1];
                int left = j - (stack.isEmpty() ? -1 : stack.peek()[0]);
                int right = i - j;
                res = (int) ((res + (long) m * left * right) % MOD);
            }
            stack.push(new int[] { i, extendedArr[i] });
        }

        return res;
    }
}

class Solution {
    public int snakesAndLadders(int[][] board) {
        int n = board.length;

        reverseBoard(board);

        boolean[] visited = new boolean[n*n+1];
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{1, 0});
        visited[1] = true;

        while(!q.isEmpty()) {
            int[] curr = q.poll();
            for(int j=1; j<=6; j++) {
                int next = curr[0] + j;
                int[] coor = squareToCoor(next, n);
                if(board[coor[0]][coor[1]] != -1) {
                    next = board[coor[0]][coor[1]];
                }
                if(next == n*n) {
                    return curr[1] + 1;
                }
                if(!visited[next]) {
                    visited[next] = true;
                    q.offer(new int[]{next, curr[1] + 1});
                }
            }
        }

        return -1;
    }

    public int[] squareToCoor(int square, int n) {
        int row = (square - 1) / n;
        int col = (square - 1) % n;
        if(row % 2 != 0) {
            col = n - 1 - col;
        }
        return new int[]{row, col};
    }

    public void reverseBoard(int[][] board) {
        int l = 0, r = board.length-1;
        while(l < r) {
            int[] temp = board[l];
            board[l] = board[r];
            board[r] = temp;
            l++;
            r--;
        }
    }
}

class Solution {
    //Using Merge Sort
    public int[] sortArray(int[] nums) {
        mergeSort(nums, 0, nums.length-1);
        return nums;
    }
    public void mergeSort(int []arr, int low, int high){
        if(low >= high) return;

        int mid = (low+high)/2;
        mergeSort(arr, low, mid);
        mergeSort(arr, mid+1, high);
        merge(arr, low, high, mid);
    }
    public void merge(int []arr, int low, int high, int mid){
        ArrayList<Integer> temp = new ArrayList<>();
        int left = low;
        int right = mid+1;

        while(left <= mid && right <= high){
            if(arr[left] <= arr[right]){
                temp.add(arr[left]);
                left++;
            }else{
                temp.add(arr[right]);
                right++;
            }
        }
        while(left <= mid){
            temp.add(arr[left]);
            left++;
        }
        while(right <= high){
            temp.add(arr[right]);
            right++;
        }
        for(int i=low; i<= high; i++){
            arr[i] = temp.get(i-low);
        }
    }
}

class Solution {
    public int maxSubarraySumCircular(int[] nums) {
        int curMax = 0, curMin = 0;
        int globMax = nums[0], globMin = nums[0];
        int total = 0;
        for (int n : nums) {
            curMax = Math.max(curMax + n, n);
            curMin = Math.min(curMin + n, n);
            total += n;
            globMax = Math.max(curMax, globMax);
            globMin = Math.min(curMin, globMin);
        }
        return globMax > 0 ? Math.max(globMax, total - globMin) : globMax;
    }
}

class Solution {
    public int numMusicPlaylists(int n, int goal, int k) {
        map = new HashMap<>();
        return (int)findPlaylists(0, goal, n, k);
    }

    HashMap<Pair, Integer> map;
    int mod = 1000000007;

    public long findPlaylists(int old_songs, int goal, int n, int k) {
        if(goal == 0 && old_songs == n) {
            return 1;
        }

        if(goal == 0 || old_songs > n) {
            return 0;
        }

        if(map.containsKey(new Pair(old_songs, goal))) {
            return map.get(new Pair(old_songs, goal));
        }

        // chossing an new_song
        long res = ((n - old_songs) * (findPlaylists(old_songs + 1, goal - 1, n, k) % mod)) % mod;

        // choose an old_songs
        if(old_songs > k) {
            res = (res + ((old_songs - k) * (findPlaylists(old_songs, goal - 1, n, k)) % mod) % mod) % mod;
        }

        map.put(new Pair(old_songs, goal), (int)res);

        return res;
    }

    class Pair {
        int a;
        int b;

        public Pair(int a, int b) {
            this.a = a;
            this.b = b;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            Pair pair = (Pair) obj;
            return a == pair.a && b == pair.b;
        }

        @Override
        public int hashCode() {
            return 31 * a + b;
        }
    }
}

