class Solution {
    public int minFallingPathSum(int[][] matrix) {
        int N = matrix.length;

        for(int r = 1; r < N; r++){
            for(int c = 0; c < N; c++){
                int mid = matrix[r-1][c];
                int left = (c > 0)? matrix[r-1][c-1]: Integer.MAX_VALUE;
                int right = (c < N-1)? matrix[r-1][c+1]: Integer.MAX_VALUE;
                matrix[r][c] = matrix[r][c] + Math.min(left, Math.min(mid, right));
            }
        }
        int res = Integer.MAX_VALUE;
        for(int i = 0; i < N; i++){
            res = Math.min(res, matrix[N-1][i]);
        }
        return res;
    }
}

/*----------------------------------
  Time Complexity: O(n^2)
  Space Complexity: (n^2)
----------------------------------*/

class Solution {
    public int minFallingPathSum(int[][] matrix) {
        int n = matrix.length;
        int[][] dp = new int[n+1][n+1];

        for(int i = n-1; i >= 0; i--){
            for(int j = 0; j < n; j++){
                if(j == 0)
                    dp[i][j] = matrix[i][j] + Math.min(dp[i+1][j], dp[i+1][j+1]);
                else if (j == n-1) {
                    dp[i][j] = matrix[i][j] + Math.min(dp[i+1][j-1], dp[i+1][j]);
                } else{
                    int min = dp[i+1][j-1];
                    if(dp[i+1][j] < min)
                        min = dp[i+1][j];
                    if(dp[i+1][j+1] < min)
                        min = dp[i+1][j+1];

                    dp[i][j] = matrix[i][j] + min;
                }
            }
        }
        int res = Integer.MAX_VALUE;
        for(int i=0; i<n; i++)
            res = Math.min(res, dp[0][i]);

        return res;
    }
}

class Solution {
    public int shortestBridge(int[][] grid) {
        Queue<int[]> q = new LinkedList<>();
        boolean[][] vis = new boolean[grid.length][grid[0].length];

        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == 1) {
                    mark(grid, vis, q, i, j);
                    i = grid.length;
                    j = grid[0].length;
                }
            }
        }
        int count = 0;
        int[][] dir = {{0,1}, {1,0}, {-1,0}, {0,-1}};

        while (!q.isEmpty()) {
            int n = q.size();

            for (int k = 0; k < n; k++) {
                int[] curr = q.poll();

                for (int j = 0; j < 4; j++) {
                    int r = curr[0] + dir[j][0];
                    int c = curr[1] + dir[j][1];

                    if (r >= 0 && c >= 0 && r < grid.length && c < grid[0].length && !vis[r][c]) {
                        if (grid[r][c] == 1) return count;
                        vis[r][c] = true;
                        q.offer(new int[]{r,c});
                    }
                }
            }
            count++;
        }
        return -1;
    }

    void mark(int[][] grid, boolean[][] vis , Queue<int[]> q, int i, int j) {
        if (i < 0 || j < 0 || i >= grid.length || j >= grid[0].length || grid[i][j] == 0 || vis[i][j]) return;
        vis[i][j] = true;
        q.add(new int[]{i,j});
        mark(grid, vis, q, i + 1, j);
        mark(grid, vis, q, i - 1, j);
        mark(grid, vis, q, i, j + 1);
        mark(grid, vis, q, i, j - 1);

    }
}

