class Solution {
    public int bagOfTokensScore(int[] tokens, int power) {
        Arrays.sort(tokens);
        int score = 0;
        int i = 0, j = tokens.length - 1;
        while (i < j) {
            if (power >= tokens[i]) {
                power -= tokens[i++];
                score += 1;
            }
            else if (score > 0 && i != j) {
                score -= 1;
                power += tokens[j--];
            }
            else
                break;
        }
        return score;
    }
}

