class Solution {
    public int subarraysDivByK(int[] nums, int k) {
        int prefix_sum = 0;
        int res = 0;
        Map<Integer, Integer> map = new HashMap<>(); // remainder -> count
        map.put(0, 1);

        for(int n: nums){
            prefix_sum += n;
            int remainder = ((prefix_sum % k) + k) % k;  // twice modulo to avoid negative remainders

            res += map.getOrDefault(remainder, 0);
            map.put(remainder, map.getOrDefault(remainder, 0) + 1);
        }
        return res;
    }
}

class Solution {

    public int[] sortedSquares(int[] nums) {

        int[] result = new int[nums.length];

        int right = nums.length - 1;
        int left = 0;
        int resultIndex = result.length - 1;
        while (left <= right) {

            if (nums[left] * nums[left] >= nums[right] * nums[right]) {
                result[resultIndex] = nums[left] * nums[left];
                left++;
            } else {
                result[resultIndex] = nums[right] * nums[right];
                right--;
            }
            resultIndex--;
        }

        return result;
    }
}

class TimeMap {

    HashMap<String, List<Pair<String, Integer>>> map;

    public TimeMap() {
        map = new HashMap<>();
    }

    public void set(String key, String value, int timestamp) {
        if (!map.containsKey(key)) map.put(key, new ArrayList<>());
        map.get(key).add(new Pair(value, timestamp));
    }

    public String get(String key, int timestamp) {
        if (!map.containsKey(key)) return "";
        List<Pair<String, Integer>> list = map.get(key);
        return search(list, timestamp);
    }

    public String search(List<Pair<String, Integer>> list, int timestamp) {
        int start = 0;
        int end = list.size() - 1;
        while (start < end) {
            int mid = start + (end - start + 1) / 2;
            if (list.get(mid).getValue() <= timestamp) start = mid; else end =
                mid - 1;
        }
        return list.get(start).getValue() <= timestamp
            ? list.get(start).getKey()
            : "";
    }
}

