class Solution {
    public String removeDuplicates(String s, int k) {
        Stack<Pair<Character, Integer>> stack = new Stack<>();
        char[] ss = s.toCharArray();

        for (char current : ss) {
            if (!stack.isEmpty() && stack.peek().getKey() == current) {
                int topCharCount = stack.pop().getValue();
                stack.push(new Pair<>(current, topCharCount + 1));
            } else {
                stack.push(new Pair<>(current, 1));
            }

            if (stack.peek().getValue() == k) {
                stack.pop();
            }
        }

        StringBuilder result = new StringBuilder();

        while (!stack.isEmpty()) {
            Pair<Character, Integer> poppedPair = stack.pop();
            for (int i = 0; i < poppedPair.getValue(); i++) {
                result.append(poppedPair.getKey());
            }
        }

        return result.reverse().toString();
    }
}

class Solution {

    Map<Character, Integer> freq;
    int[] scoree;

    public int maxScoreWords(String[] words, char[] letters, int[] score) {
        scoree = score;
        freq = new HashMap<>();
        for(char c: letters){
            freq.put(c, freq.getOrDefault(c, 0) + 1);
        }

        return backtrack(words, 0);
    }
    private int backtrack(String[] words, int idx){
        if(idx == words.length)
            return 0;

        int res = backtrack(words, idx + 1);
        if(can_form_word(words[idx])){
            for(char c: words[idx].toCharArray())
                freq.put(c, freq.get(c) - 1);

            res = Math.max(res, get_score(words[idx]) + backtrack(words, idx + 1));
            for(char c: words[idx].toCharArray())
                freq.put(c, freq.get(c) + 1);
        }
        return res;
    }
    private boolean can_form_word(String s){
        Map<Character, Integer> map = new HashMap<>();
        for(char c: s.toCharArray())
            map.put(c, map.getOrDefault(c, 0) + 1);

        for(char c: map.keySet()){
            if(!freq.containsKey(c) || map.get(c) > freq.get(c))
                return false;
        }
        return true;
    }
    private int get_score(String s){
        int score = 0;
        for(char c: s.toCharArray()){
            score += scoree[c - 'a'];
        }
        return score;
    }
}

class Solution {
    int[][] intervals;
    Integer[] cache;

    public int jobScheduling(int[] startTime, int[] endTime, int[] profit) {
        int n = startTime.length;
        intervals = new int[n][3];
        cache = new Integer[n];

        for (int i = 0; i < n; i++) {
            intervals[i] = new int[]{startTime[i], endTime[i], profit[i]};
        }

        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));

        return dfs(0);
    }

    private int dfs(int i) {
        if (i == intervals.length) {
            return 0;
        }

        if (cache[i] != null) {
            return cache[i];
        }

        // don't include
        int res = dfs(i + 1);

        // include
        int j = binarySearch(intervals, i, intervals[i][1]);
        cache[i] = res = Math.max(res, intervals[i][2] + dfs(j));

        return res;
    }

    private int binarySearch(int[][] intervals, int start, int target) {
        int left = start + 1;
        int right = intervals.length - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (intervals[mid][0] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return left;
    }
}

class Solution {
    public int numberOfSubarrays(int[] nums, int k) {
        int res = 0, odds = 0;
        int l = 0, m = 0;

        for(int r = 0; r < nums.length; r++){
            if(nums[r] % 2 == 1)
                odds += 1;

            while(odds > k){
                if(nums[l] % 2 == 1)
                    odds -= 1;
                l += 1;
                m = l;
            }

            if(odds == k){
                while(nums[m] % 2 != 1){
                    m += 1;
                }
                res += m - l + 1;
            }
        }
        return res;
    }
}

class Solution {
    public int maxScoreWords(String[] words, char[] letters, int[] score) {
        int[] letterCount = new int[26];
        for (char letter : letters) {
            letterCount[letter - 'a'] += 1;
        }
        return backtrack(0, words, score, letterCount);
    }

    private int backtrack(int i, String[] words, int[] score, int[] letterCount) {
        if (i == words.length) {
            return 0;
        }
        int res = backtrack(i + 1, words, score, letterCount);
        String word = words[i];
        if (canFormWord(word, letterCount)) {
            for (char ch : word.toCharArray()) {
                letterCount[ch - 'a'] -= 1;
            }
            res = Math.max(res, getScore(word, score) + backtrack(i + 1, words, score, letterCount));
            for (char ch : word.toCharArray()) {
                letterCount[ch - 'a'] += 1;
            }
        }
        return res;
    }

    private boolean canFormWord(String word, int[] letterCount) {
        int[] wordCount = new int[26];
        for (char ch : word.toCharArray()) {
            wordCount[ch - 'a'] += 1;
        }
        for (int i = 0; i < 26; i++) {
            if (wordCount[i] > letterCount[i]) {
                return false;
            }
        }
        return true;
    }

    private int getScore(String word, int[] score) {
        int total = 0;
        for (char ch : word.toCharArray()) {
            total += score[ch - 'a'];
        }
        return total;
    }
}

class Solution {
    static final int ROW = 0, COL = 1;
    public List<List<Integer>> shiftGrid(int[][] grid, int k) {
        final int M = grid.length, N = grid[0].length;

        BiFunction<Integer, Integer, Integer> posToVal = (r, c) ->
            r * N + c;
        Function<Integer, int[]> valToPos = (v) ->
            new int[] {v / N, v % N};

        List<List<Integer>> res = new ArrayList<>();
        for(int i = 0; i < M; i++) {
            Integer[] tmp = new Integer[N];
            for(int j = 0; j < N; j++)
                tmp[j] = 0;
            res.add(Arrays.asList(tmp));
        }
        for(int r = 0; r < M; r++)
            for(int c = 0; c < N; c++) {
                int newVal = (posToVal.apply(r, c) + k) % (M * N);
                int[] newRC = valToPos.apply(newVal);
                res.get(newRC[ROW]).set(newRC[COL], grid[r][c]);
            }
        return res;
    }
}

class Solution {
    public List<List<String>> suggestedProducts(String[] products, String searchWord) {
        List<List<String>> res = new ArrayList<>();
        Arrays.sort(products);

        int l = 0;
        int r = products.length - 1;
        for (int i = 0; i < searchWord.length(); i++) {
            while (l <= r && (products[l].length() <= i || products[l].charAt(i) != searchWord.charAt(i)))
                l++;
            while (l <= r && (products[r].length() <= i || products[r].charAt(i) != searchWord.charAt(i)))
                r--;

            List<String> list = new ArrayList<>();
            for (int j = l; j < l + 3 && j <= r; j++) {
                list.add(products[j]);
            }
            res.add(list);
        }
        return res;
    }
}

/*      Top-Down Approach
-------------------------------------
  Time Complexity: O(n*min(n,m))
  Space Complexity: O(n*min(n,m))
------------------------------------*/
class Solution {
    Map<String, Integer> memo;
    int MOD = (int)1e9+7;
    public int numWays(int steps, int arrLen){
        memo = new HashMap<>();
        return dfs(0, steps, arrLen);
    }
    private int dfs(int i, int steps, int n){
        String pos = i + "," + steps;
        if(memo.containsKey(pos))
            return memo.get(pos);
        if(steps == 0 && i == 0)
            return 1;
        if(i < 0 || i > n-1 || steps == 0)
            return 0;

        long left = dfs(i-1, steps-1, n);
        long stay = dfs(i, steps-1, n);
        long right = dfs(i+1, steps-1, n);
        int res = (int)((left + stay + right)%MOD);
        memo.put(pos, res);
        return res;
    }
}

/*      Bottom-Up Approach
------------------------------------
  Time Complexity: O(n*min(n,m))
  Space Complexity: O(n*min(n,m))
-----------------------------------*/
class Solution {
    public int numWays(int steps, int arrLen) {
        int MOD = (int)1e9+7;
        arrLen = Math.min(arrLen, steps);
        int[][] dp = new int[steps + 1][arrLen];

        dp[0][0] = 1;

        for (int step = 1; step <= steps; step++) {
            for (int pos = 0; pos < arrLen; pos++) {
                dp[step][pos] = dp[step - 1][pos];

                if (pos - 1 >= 0) {
                    dp[step][pos] = (dp[step][pos] + dp[step - 1][pos - 1]) % MOD;
                }
                if (pos + 1 < arrLen) {
                    dp[step][pos] = (dp[step][pos] + dp[step - 1][pos + 1]) % MOD;
                }
            }
        }

        return dp[steps][0];
    }
}

class Solution {

    public String tictactoe(int[][] moves) {
        int[][][] result = new int[2][2][3];
        int[][] diag1 = new int[2][1];
        int[][] diag2 = new int[2][1];

        int p = 0;
        for (int i = 0; i < moves.length; i++) {
            int r = moves[i][0];
            int c = moves[i][1];

            if (++result[p][0][r] == 3) return getWinner(p);
            if (++result[p][1][c] == 3) return getWinner(p);

            if (r == c) if (++diag1[p][0] == 3) return getWinner(p);

            if (
                (r == 1 && c == 1) || (r == 0 && c == 2) || (r == 2 && c == 0)
            ) if (++diag2[p][0] == 3) return getWinner(p);

            if (p == 0) p = 1; else p = 0;
        }

        return moves.length == 9 ? "Draw" : "Pending";
    }

    private String getWinner(int p) {
        return p == 0 ? "A" : "B";
    }
}

class Solution {
    public List<Integer> sequentialDigits(int low, int high) {
        List<Integer> res = new ArrayList<>();
        Queue<Integer> q = new LinkedList<>();
        for(int i = 1; i < 10; i++)
            q.add(i);

        while(!q.isEmpty()){
            int n = q.poll();
            if(n > high)
                continue;
            if(n >= low && n <= high)
                res.add(n);
            int ones = n % 10;
            if(ones < 9)
                q.add(n * 10 + (ones + 1));
        }
        return res;
    }
}

