class Solution {
    public boolean validateBinaryTreeNodes(int n, int[] leftChild, int[] rightChild) {
        int root = findRoot(n, leftChild, rightChild);
        if(root == -1)
            return false;

        Set<Integer> visited = new HashSet<>();
        Queue<Integer> q = new LinkedList<>();

        q.add(root);
        visited.add(root);

        while(!q.isEmpty()){
            int node = q.poll();
            int[] childerns = {leftChild[node], rightChild[node]};

            for(int c: childerns){
                if(c == -1)
                    continue;
                if(visited.contains(c))
                    return false;
                q.add(c);
                visited.add(c);
            }
        }
        return visited.size() == n;
    }
    private int findRoot(int n, int[] leftChild, int[] rightChild){
        Set<Integer> set = new HashSet<>();
        for(int lc: leftChild)
            set.add(lc);
        for(int rc: rightChild)
            set.add(rc);

        for(int i = 0; i < n; i++){
            if(!set.contains(i))
                return i;
        }
        return -1;
    }
}

class Solution {
    public int findTheLongestSubstring(String s) {
        char[] char_mask = {1,0,0,0,2,0,0,0,4,0,0,0,0,0,8,0,0,0,0,0,16,0,0,0,0,0};
        int crr_mask = 0, res = 0;
        int[] mask_map = new int[32];
        Arrays.fill(mask_map, -1);

        for(int i = 0; i < s.length(); i++){
            crr_mask ^= char_mask[s.charAt(i) - 'a'];
            if(crr_mask != 0 && mask_map[crr_mask] == -1){
                mask_map[crr_mask] = i;
            }
            res = Math.max(res, i - mask_map[crr_mask]);
        }

        return res;
    }
}

class Solution {

    public int numOfMinutes(int n, int headID, int[] manager, int[] informTime) {
        Map<Integer, List<Integer>> adjacentMap = prepareAdjacentMap(headID, manager);

        int time = 0;

        Deque<Pair<Integer, Integer>> deque = new ArrayDeque<>();
        deque.addFirst(new Pair<>(headID, informTime[headID]));

        while (!deque.isEmpty()) {
            Pair<Integer, Integer> curManager = deque.pollLast();
            time = Math.max(time, curManager.getValue());

            if (adjacentMap.containsKey(curManager.getKey())) {
                for (Integer employee : adjacentMap.get(curManager.getKey())) {
                    deque.addFirst(new Pair<>(employee, curManager.getValue() + informTime[employee]));
                }
            }
        }

        return time;
    }

    private Map<Integer, List<Integer>> prepareAdjacentMap(int headId, int[] manager) {
        Map<Integer, List<Integer>> adjacentMap = new HashMap<>();

        for (int i = 0; i < manager.length; i++) {
            if (i == headId) {
                continue;
            }
            if (!adjacentMap.containsKey(manager[i])) {
                adjacentMap.put(manager[i], new ArrayList<>());
            }
            adjacentMap.get(manager[i]).add(i);
        }

        return adjacentMap;
    }
}

class UndergroundSystem {
    // id, src, time
    Map<Integer, Pair<String, Integer>> entries;
    // src, dest, int[total time, number of travels]
    Map<String, Map<String, int[]>> times;

    public UndergroundSystem() {
        this.entries = new HashMap<>();
        this.times = new HashMap<>();
    }

    public void checkIn(int id, String stationName, int t) {
        entries.put(id, new Pair<>(stationName, t));
    }

    public void checkOut(int id, String dest, int t) {
        Pair<String, Integer> entry = entries.get(id);
        String src = entry.getKey();
        int duration = t - entry.getValue();

        Map<String, int[]> city = times.getOrDefault(src, new HashMap<>());
        int[] total = city.getOrDefault(dest, new int[2]);
        total[0] += duration;
        total[1]++;
        city.put(dest, total);
        times.put(src, city);
    }

    public double getAverageTime(String startStation, String endStation) {
        int[] total = times.get(startStation).get(endStation);
        return 1.0 * total[0] / total[1];
    }
}

