class Solution {
    public int maxVowels(String s, int k) {
        Set<Character> set = new HashSet<>();
        Collections.addAll(set, 'a', 'e', 'i', 'o', 'u');

        int l=0, cnt=0, res=0;

        for(int r=0; r<s.length(); r++){
            cnt += set.contains(s.charAt(r))?1:0;
            if(r-l+1 > k){
                cnt -= set.contains(s.charAt(l))?1:0;
                l++;
            }
            res = Math.max(res, cnt);
        }
        return res;
    }
}

class Solution {
    Map<Integer, Integer> count = new HashMap<>();
    int odd = 0;

    public int pseudoPalindromicPaths(TreeNode root) {
        return dfs(root);
    }

    private int dfs(TreeNode curr) {
        if (curr == null) {
            return 0;
        }

        count.put(curr.val, count.getOrDefault(curr.val, 0) + 1);
        int oddChange = count.get(curr.val) % 2 == 1 ? 1 : -1;
        odd += oddChange;

        int res = 0;
        if (curr.left == null && curr.right == null) {
            res = (odd <= 1) ? 1 : 0;
        } else {
           res = dfs(curr.left) + dfs(curr.right);
        }

        odd -= oddChange;
        count.put(curr.val, count.get(curr.val) - 1);
        return res;
    }
}

