            else
                freq.put(n, 1);
        }
        return res;
    }
}

class Solution {
    public double maxProbability(int n, int[][] edges, double[] succProb, int start, int end) {
        // create the graph
        List<double[]>[] graph = new LinkedList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new LinkedList<>();
        }

        for (int i = 0; i < edges.length; i++) {
            double from =  edges[i][0];
            double to =  edges[i][1];
            double weight = succProb[i];
            double[] m = new double[2];
            m[0] = to;
            m[1] = weight;
            graph[edges[i][0]].add(m);
            double[] k = new double[2];
            k[0] = from;
            k[1] = weight;
            graph[edges[i][1]].add(k);
        }

        // call dijkstra and return
        return dijkstra(start, end, graph);
    }

    class State{
        int id;
        double proToStart;

        public State(int id, double proToStart){
            this.id = id;
            this.proToStart = proToStart;
        }
    }

    private double dijkstra(int start, int end, List<double[]>[] graph){
        double[] proTo = new double[graph.length];
        // 初始化为一个去不到的值
        Arrays.fill(proTo, -1);
        proTo[start] = 1;

        PriorityQueue<State> pq = new PriorityQueue<State>((a, b) -> {
        return Double.compare(b.proToStart, a.proToStart);
    });
        pq.offer(new State(start, 1));

        while (!pq.isEmpty()){
            State cur = pq.poll();
            int curid = cur.id;
            double curproToStart = cur.proToStart;

            if (curid == end) {
                return curproToStart;
            }

            if (proTo[curid] > curproToStart) {
                continue;
            }

            List<double[]> nexts = graph[curid];
            for (double[] next: nexts) {
                double proToNext = proTo[curid] * next[1];
                int idx = (int) next[0];
                if (proToNext > proTo[idx]) {
                    proTo[idx] = proToNext;
                    pq.offer(new State(idx, proToNext));
                }
            }
        }

        return 0;
    }
}

class Solution {
    Map<String, Integer> cache;

    public int getLengthOfOptimalCompression(String s, int k) {
        cache = new HashMap<>();
        return count(0, k, '\0', 0, s);
    }
    private int count(int i, int k, char prev, int prev_count, String s){
        String curr_state = i + "," + k + "," + prev + "," + prev_count;

        if(cache.containsKey(curr_state))
            return cache.get(curr_state);
        if(k < 0)
            return Integer.MAX_VALUE;
        if(i == s.length())
            return 0;

        int res = -1;
        if(s.charAt(i) == prev){
            int incr = (prev_count == 1 || prev_count == 9 || prev_count == 99)? 1: 0;
            res = incr + count(i + 1, k, prev, prev_count + 1, s);
        }
        else{
            res = Math.min(count(i + 1, k - 1, prev, prev_count, s),
                            1 + count(i + 1, k, s.charAt(i), 1, s));
        }
        cache.put(curr_state, res);
        return res;
    }
}

