class Solution {
    public char findKthBit(int n, int k) {
        int length = (int)Math.pow(2, n) - 1;

        return helper(length, k);
    }

    private char helper(int length, int k){
        if(length == 1)
            return '0';

        int half = length/2;

        if(k <= half){
            return helper(half, k);
        }
        else if(k > half + 1){
            char res = helper(half, 1 + length - k);
            return (res == '0')? '1': '0';
        }
        else{
            return '1';
        }
    }
}

class Solution {
    public int minDays(int n) {
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(0, 0);
        dp.put(1, 1);
        return dfs(n, dp);
    }

    private int dfs(int n, Map<Integer, Integer> dp) {
        if (dp.containsKey(n)) {
            return dp.get(n);
        }
        int optionOne = 1 + n % 2 + dfs(n / 2, dp);
        int optionTwo = 1 + n % 3 + dfs(n / 3, dp);
        dp.put(n, Math.min(optionOne, optionTwo));
        return dp.get(n);
    }
}

