class Solution {
    public boolean isEvenOddTree(TreeNode root) {
        Queue<TreeNode> q = new LinkedList<>();
        q.add(root);
        boolean evenLevel = true;

        while(!q.isEmpty()){
            int prev = (evenLevel)? Integer.MIN_VALUE: Integer.MAX_VALUE;
            int sz = q.size();

            for(int i = 0; i < sz; i++){
                TreeNode curr = q.poll();
                int nodeVal = curr.val;

                if((evenLevel && nodeVal % 2 == 0) || (!evenLevel && nodeVal % 2 != 0))
                    return false;
                if((evenLevel && nodeVal <= prev) || (!evenLevel && nodeVal >= prev))
                    return false;

                prev = nodeVal;

                if(curr.left != null)
                    q.add(curr.left);
                if(curr.right != null)
                    q.add(curr.right);
            }
            evenLevel = !evenLevel;
        }
        return true;
    }
}

class Solution {
    public int minimumOneBitOperations(int n) {
        if(n == 0)
            return 0;

        int k = 0;
        while((int)Math.pow(2,k) <= n)
            k += 1;
        k -= 1;
        return (int)Math.pow(2,k+1) - 1 - minimumOneBitOperations((int)Math.pow(2,k) ^ n);
    }
}

