// Min Heap comparator for reverse priority queue
class StringNumberComparartor implements Comparator<String> {
    @Override
    public int compare(String s1, String s2) {
        if(s1.length() != s2.length()) {
            return (s1.length() - s2.length());
        }
        int len = s1.length();
        for(int i=0; i<len; i++) {
            char c1 = s1.charAt(i), c2 = s2.charAt(i);
            if(c1 == c2) { continue; }
            return (c1 - c2);
        }
        return 0;
    }
}

class Solution {
    public String kthLargestNumber(String[] nums, int k) {
        // Reverse pq to store only k elements [i.e. Min Heap]
        PriorityQueue<String> pq = new PriorityQueue<>(new StringNumberComparartor());

        for(String numStr: nums) {
            pq.add(numStr);
            if(pq.size() > k) {
                pq.remove();
            }
        }

        return pq.peek();
    }
}

class Solution {
    private final int[] parent;
    private final int[] locked;
    private final Map<Integer, List<Integer>> child;

    public LockingTree(int[] parent) {
        this.parent = parent;
        locked = new int[parent.length];
        child = new HashMap<>();

        for (int i = 0; i < parent.length; i++) {
            child.putIfAbsent(parent[i], new ArrayList<>());
            child.putIfAbsent(i, new ArrayList<>());
            child.get(parent[i]).add(i);
        }
    }

    public boolean lock(int num, int user) {
        if (locked[num] <= 0) {
            locked[num] = user;
            return true;
        }

        return false;
    }

    public boolean unlock(int num, int user) {
        if (locked[num] == user) {
            locked[num] = 0;
            return true;
        }

        return false;
    }

    public boolean upgrade(int num, int user) {
        if (!noneAncestorsLocked(num)) {
            return false;
        }

        int lockedCount = checkDescendantsAndLockIfNeeded(num);

        if (lockedCount > 0) {
            locked[num] = user;
        }

        return lockedCount > 0;
    }

    private boolean noneAncestorsLocked(int num) {
        while (num != -1) {
            if (locked[num] != 0) {
                return false;
            }
            num = parent[num];
        }

        return true;
    }

    private int checkDescendantsAndLockIfNeeded(int num) {
        int lockedCount = 0;
        Deque<Integer> deque = new ArrayDeque<>();

        deque.addFirst(num);
        while (!deque.isEmpty()) {
            int n = deque.pollLast();
            if (locked[n] > 0) {
                lockedCount++;
                locked[n] = 0;
            }
            for (Integer i : child.get(n)) {
                deque.addFirst(i);
            }
        }

        return lockedCount;
    }
}

