class Solution {
    public int maxProduct(String s) {
    int[] dp = new int[4096];
    int res = 0, mask = (1 << s.length()) - 1;
    for (int m = 1; m <= mask; ++m)
        dp[m] = palSize(s, m);
    for (int m1 = mask; m1 > 0; --m1)
        if (dp[m1] * (s.length() - dp[m1]) > res)
            for(int m2 = mask ^ m1; m2 > 0; m2 = (m2 - 1) & (mask ^ m1))
                res = Math.max(res, dp[m1] * dp[m2]);
    return res;
}
private int palSize(String s, int mask) {
    int p1 = 0, p2 = s.length(), res = 0;
    while (p1 <= p2) {
        if ((mask & (1 << p1)) == 0)
            ++p1;
        else if ((mask & (1 << p2)) == 0)
            --p2;
        else if (s.charAt(p1) != s.charAt(p2))
            return 0;
        else
            res += 1 + (p1++ != p2-- ? 1 : 0);
    }
    return res;
}
}

class Solution {
    public int minOperations(int[] nums) {
        int length = nums.length;
        Set<Integer> set = new HashSet<>();

        for(int num : nums)
            set.add(num);

        int[] newNums = new int[set.size()];
        int idx = 0;
        for(int num : set)
            newNums[idx++] = num;

        Arrays.sort(newNums);
        int res = length;
        int r = 0;

        for(int l = 0; l < newNums.length; l++){
            while(r < newNums.length && newNums[r] < newNums[l] + length)
                r += 1;
            int window = r - l;
            res = Math.min(res, length - window);
        }
        return res;
    }
}

class Solution {
    public long gridGame(int[][] grid) {
        long[] prefix_top = new long[grid[0].length];
        long[] prefix_bottom = new long[grid[0].length];
        for(int i = 0; i < grid[0].length; i++)
        {
            prefix_top[i] = grid[0][i];
            prefix_bottom[i] = grid[1][i];
        }
        for(int i = 1; i < grid[0].length; i++)
        {
            prefix_top[i] += prefix_top[i - 1];
            prefix_bottom[i] += prefix_bottom[i - 1];
        }
        long res = Long.MAX_VALUE;
        long maxi = Long.MIN_VALUE;
        for(int i = 0; i < grid[0].length; i++)
        {
            long top = prefix_top[grid[0].length - 1] - prefix_top[i];
            long bottom = 0;
            if(i > 0)
            {
                bottom = prefix_bottom[i - 1];
            }
            maxi = Math.max(top, bottom);
            res = Math.min(res, maxi);
        }
        return res;
    }
}

