public class Solution {
    public int minimumTime(int n, int[][] relations, int[] time) {
        Map<Integer, List<Integer>> adj = new HashMap<>();
        for (int[] relation : relations) {
            int src = relation[0];
            int dst = relation[1];
            adj.putIfAbsent(src, new ArrayList<>());
            adj.get(src).add(dst);
        }

        Map<Integer, Integer> maxTime = new HashMap<>();

        for (int i = 1; i <= n; i++) {
            dfs(i, time, adj, maxTime);
        }

        return maxTime.values().stream().max(Integer::compareTo).get();
    }

    private int dfs(int src, int[] time, Map<Integer, List<Integer>> adj, Map<Integer, Integer> maxTime) {
        if (maxTime.containsKey(src)) {
            return maxTime.get(src);
        }

        int res = time[src - 1];
        for (int nei : adj.getOrDefault(src, new ArrayList<>())) {
            res = Math.max(res, time[src - 1] + dfs(nei, time, adj, maxTime));
        }
        maxTime.put(src, res);
        return res;
    }
}

public class Solution {
    public List<Integer> findAllPeople(int n, int[][] meetings, int firstPerson) {
        Set<Integer> secrets = new HashSet<>(Arrays.asList(0, firstPerson));
        Map<Integer, Map<Integer, List<Integer>>> timeMap = new HashMap<>();

        for (int[] meeting : meetings) {
            int src = meeting[0], dst = meeting[1], time = meeting[2];
            timeMap.putIfAbsent(time, new HashMap<>());
            timeMap.get(time).putIfAbsent(src, new ArrayList<>());
            timeMap.get(time).putIfAbsent(dst, new ArrayList<>());
            timeMap.get(time).get(src).add(dst);
            timeMap.get(time).get(dst).add(src);
        }

        for (Integer time : new TreeSet<>(timeMap.keySet())) {
            Set<Integer> visit = new HashSet<>();
            for (Integer src : timeMap.get(time).keySet()) {
                if (secrets.contains(src)) {
                    dfs(src, timeMap.get(time), visit, secrets);
                }
            }
        }

        return new ArrayList<>(secrets);
    }

    private void dfs(int src, Map<Integer, List<Integer>> adj, Set<Integer> visit, Set<Integer> secrets) {
        if (visit.contains(src)) {
            return;
        }
        visit.add(src);
        secrets.add(src);
        for (Integer nei : adj.get(src)) {
            dfs(nei, adj, visit, secrets);
        }
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        int n = 5;
        int[][] meetings = { { 0, 1, 2 }, { 1, 2, 3 }, { 2, 3, 4 }, { 4, 5, 5 } };
        int firstPerson = 1;
        List<Integer> result = solution.findAllPeople(n, meetings, firstPerson);
        System.out.println(result);
    }
}

public class Solution {

    public String firstPalindrome(String[] words) {
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            int x = 0, y = word.length() - 1;
            while (word.charAt(x) == word.charAt(y)) {
                if (x >= y)
                    return word;
                else {
                    x++;
                    y--;
                }
            }
        }
        return "";
    }

}

class Solution {
    public int numberOfBeams(String[] bank) {
        int prev = countOnes(bank[0]);
        int res = 0;

        for(int i = 1; i < bank.length; i++){
            int curr = countOnes(bank[i]);
            if(curr > 0){
                res += curr*prev;
                prev = curr;
            }
        }
        return res;
    }
    private int countOnes(String str){
        int res = 0;
        for(char c: str.toCharArray())
            res += (c == '1')? 1: 0;
        return res;
    }
}

//The basic idea is to use the slow and fast pointers to find the mid
// Once found we will reverse the second half of the Linkedlist and compare the values

class Solution {
    public ListNode reverse(ListNode head){
        if(head == null) return head;

        ListNode curr = head;
        ListNode prev = null;

        while(curr != null){
            ListNode nxt = curr.next;
            curr.next = prev;
            prev = curr;
            curr = nxt;
        }
        return prev;
    }
    public int pairSum(ListNode head) {
        int mx = Integer.MIN_VALUE;

        ListNode slow=head, fast=head;

        while(fast != null && fast.next != null){
            fast = fast.next.next;
            slow = slow.next;
        }

        ListNode prev = reverse(slow);

        ListNode head1 = head, head2 = prev;
        while(head2 != null){
            mx = Math.max(mx, head1.val+head2.val);
            head1 = head1.next;
            head2 = head2.next;
        }
        return mx;
    }
}

class Solution {
    public int numberOfWays(String corridor) {
        int MOD = (int)1e9 + 7;
        List<Integer> seatIdx = new ArrayList<>();

        for(int i = 0; i < corridor.length(); i++){
            if(corridor.charAt(i) == 'S')
                seatIdx.add(i);
        }
        if(seatIdx.size() == 0 || seatIdx.size()%2 == 1)
            return 0;

        long res = 1;
        for(int i = 2; i < seatIdx.size(); i += 2){
            res = res*(seatIdx.get(i) - seatIdx.get(i-1)) % MOD;
        }
        return (int)res;
    }
}

public class Solution {
    public int[] rearrangeArray(int[] nums) {
        int i = 0, j = 1;
        int[] res = new int[nums.length];
        for (int k = 0; k < nums.length; k++) {
            if (nums[k] > 0) {
                res[i] = nums[k];
                i += 2;
            } else {
                res[j] = nums[k];
                j += 2;
            }
        }
        return res;
    }
}

class Solution {
    public List<List<Integer>> findDifference(int[] nums1, int[] nums2) {
        List<List<Integer>> res = new ArrayList<>();

        List<Integer> num1 = new ArrayList<>();
        for(int n: nums1) num1.add(n);

        List<Integer> num2 = new ArrayList<>();
        for(int n: nums2) num2.add(n);

        Set<Integer> set1 = new HashSet<>();
        Set<Integer> set2 = new HashSet<>();

        //Because we need to return result in 2 list of the result list, therefore we are creating these placeholders
        res.add(new ArrayList<>());
        res.add(new ArrayList<>());

        for(int i=0; i<nums1.length; i++){
            if(!num2.contains(nums1[i])) set1.add(nums1[i]);
        }

        for(int i=0; i<nums2.length; i++){
            if(!num1.contains(nums2[i])) set2.add(nums2[i]);
        }

        for(int n: set1) res.get(0).add(n);

        for(int n: set2) res.get(1).add(n);

        return res;
    }
}

