class Solution {
    public List<List<Integer>> findWinners(int[][] matches) {
        Map<Integer, Integer> map = new TreeMap<>(); // Store player as key and loses as value
        for(int[] arr: matches){
            int winner = arr[0], loser = arr[1];
            map.put(winner, map.getOrDefault(winner, 0));
            map.put(loser, map.getOrDefault(loser, 0) + 1);
        }

        List<List<Integer>> res = new ArrayList<>();
        res.add(new ArrayList<>());
        res.add(new ArrayList<>());
        for(int player: map.keySet()){
            int loses = map.get(player);
            if(loses == 0)
                res.get(0).add(player);
            else if(loses == 1)
                res.get(1).add(player);
        }
        return res;
    }
}

class Solution {
    public int[] fullBloomFlowers(int[][] flowers, int[] people) {
        List<Integer> starts = new ArrayList<>();
        List<Integer> ends = new ArrayList<>();

        for(int[] flwr: flowers){
            starts.add(flwr[0]);
            ends.add(flwr[1] + 1);
        }

        Collections.sort(starts);
        Collections.sort(ends);
        int[] res = new int[people.length];

        for(int i = 0; i < people.length; i++){
            int person = people[i];
            int startBlooming = BinarySearch(starts, person);
            int stopBlooming = BinarySearch(ends, person);
            res[i] = startBlooming - stopBlooming;
        }
        return res;
    }

    private int BinarySearch(List<Integer> ls, int target){
        int l = 0;
        int r = ls.size();

        while(l < r){
            int m = l + (r-l)/2;
            if(target < ls.get(m))
                r = m;
            else
                l = m + 1;
        }
        return l;
    }
}

class Solution {
    public String largestGoodInteger(String num) {
        String res = "";

        for(int i = 0; i <= num.length()-3; i++){
            String curr = num.substring(i, i+3);
            if(curr.charAt(0) == curr.charAt(1) && curr.charAt(0) == curr.charAt(2))
                res = (curr.compareTo(res) > 0) ? curr: res;
        }
        return res;
    }
}

class Solution {
    public int[] successfulPairs(
        int[] spells, int[] potions, long success) {
        int [] res = new int[spells.length];
        Arrays.sort(potions);
        for(int i=0;i<spells.length;i++){
            int spell = spells[i];
            int l = 0, r = potions.length-1;
            while(l<=r){
                int m = l+(r-l)/2;
                if((long)spell*potions[m]>=success) r=m-1;
                else l=m+1;
            }
            res[i] = (l<potions.length)?potions.length-l:0;
        }
        return res;
    }
}

class Solution {
    public long distinctNames(String[] ideas) {
        Map<Character, Set<String>> map = new HashMap<>();
        for (String s : ideas) {
            char key = s.charAt(0);
            String val = s.substring(1, s.length());
            Set<String> set = map.getOrDefault(key, new HashSet<>());
            set.add(val);
            map.put(key, set);
        }

        long res = 0;
        for (char key1 : map.keySet()) {
            Set<String> set1 = map.get(key1);
            for (char key2 : map.keySet()) {
                if (key1 == key2) continue;
                Set<String> set2 = map.get(key2);
                int overlap = 0;
                for (String s : set1) {
                    if (set2.contains(s)) overlap++;
                }
                res += (set1.size() - overlap) * (set2.size() - overlap);
            }
        }
        return res;
    }
}

