/*--------------------------
  Time Complexity: O(n)
  Space Complexity: O(n)
---------------------------*/
class Solution {
    public int amountOfTime(TreeNode root, int start) {
        Map<Integer, List<Integer>> g = treeTograph(root);
        int time = 0;
        Queue<Integer> q = new LinkedList<>();
        Set<Integer> visited = new HashSet<>();
        q.add(start);
        visited.add(start);

        while(!q.isEmpty()){
            int size = q.size();
            for (int i = 0; i < size; i++) {
                int curr = q.poll();
                for (int neighbour : g.get(curr)) {
                    if (!visited.contains(neighbour)) {
                        q.add(neighbour);
                        visited.add(neighbour);
                    }
                }
            }
            time++;
        }
        return time-1;
    }
    public HashMap<Integer, List<Integer>> treeTograph(TreeNode root) {
        HashMap<Integer, List<Integer>> graph = new HashMap<>();
        buildGraph(root, graph);
        return graph;
    }

    private void buildGraph(TreeNode node, HashMap<Integer, List<Integer>> graph) {
        if (node == null) {
            return;
        }

        graph.putIfAbsent(node.val, new ArrayList<>());

        if (node.left != null) {
            graph.get(node.val).add(node.left.val);
            graph.putIfAbsent(node.left.val, new ArrayList<>());
            graph.get(node.left.val).add(node.val);
            buildGraph(node.left, graph);
        }

        if (node.right != null) {
            graph.get(node.val).add(node.right.val);
            graph.putIfAbsent(node.right.val, new ArrayList<>());
            graph.get(node.right.val).add(node.val);
            buildGraph(node.right, graph);
        }
    }
}

class Solution {
    public String removeStars(String s) {

        // Create a new stack to keep track of characters encountered so far
        Stack<Character> stk = new Stack<>();

        // Iterate over each character in the input string
        for (char c : s.toCharArray()) {
            // If the current character is a star,
            // remove the topmost character from the stack
            if (c == '*') {
                stk.pop();
            }
            // If the current character is not a star, add it to the stack
            else {
                stk.push(c);
            }
        }

        // StringBuilder to store the characters in the stack
        StringBuilder sb = new StringBuilder();
        for (char c : stk) {
            sb.append(c);
        }

        // Convert the StringBuilder to a string and return it as the output
        return sb.toString();
    }
}

