}

class Solution {
    long res = 0;
    HashMap<Integer, List<Integer>> g = new HashMap<>();
    public long minimumFuelCost(int[][] roads, int seats) {
        for(int[] e : roads){
            int a = e[0], b = e[1];
            g.computeIfAbsent(a, val -> new ArrayList<>()).add(b);
            g.computeIfAbsent(b, val -> new ArrayList<>()).add(a);
        }
        if (g.size() == 0)
            return 0;

        dfs(0, -1, seats);
        return res;
    }

    private int dfs(int node, int parent, int seats){
        int passengers = 0;

        for(int child : g.get(node)){
            if(child != parent){
                int p = dfs(child, node, seats);
                passengers += p;
                res += (int) Math.ceil((double)p/seats);
            }
        }
        return passengers + 1;
    }
}

class Solution {
    public int[][] onesMinusZeros(int[][] grid) {
        int r = grid.length, c = grid[0].length;
        int[] onesRow = new int[r];
        int[] onesCol = new int[c];

        for(int i = 0; i < r; i++){
            for(int j = 0; j < c; j++){
                onesRow[i] += grid[i][j];
                onesCol[j] += grid[i][j];
            }
        }

        int[][] res = new int[r][c];
        for(int i = 0; i < r; i++){
            for(int j = 0; j < c; j++){
                int no = 2 * onesRow[i] + 2 * onesCol[j] - r - c;
                res[i][j] = no;
            }
        }
        return res;
    }
}

class Solution {
    public int bestClosingTime(String cust) {
        int n = cust.length();
        int[] pre_n = new int[n+1];
        int[] post_y = new int[n+1];

        for(int i = 1; i <= n; i++){
            pre_n[i] = pre_n[i-1];
            if(cust.charAt(i-1) == 'N')
                pre_n[i]++;
        }
        for(int i = n-1; i >= 0; i--){
            post_y[i] = post_y[i+1];
            if(cust.charAt(i) == 'Y')
                post_y[i]++;
        }

        int min_penalty = Integer.MAX_VALUE, idx = 0;

        for(int i = 0; i <= n; i++){
            int penalty = pre_n[i] + post_y[i];
            if(penalty < min_penalty){
                min_penalty = penalty;
                idx = i;
            }
        }
        return idx;
    }
}

