class Solution {
    public List<List<Integer>> findMatrix(int[] nums) {
        Map<Integer, Integer> count = new HashMap<>();
        List<List<Integer>> res = new ArrayList<>();

        for (int n : nums) {
            int row = count.getOrDefault(n, 0);
            if (res.size() == row) {
                res.add(new ArrayList<>());
            }
            res.get(row).add(n);
            count.put(n, count.getOrDefault(n, 0) + 1);
        }

        return res;
    }
}

class Solution {
    public int minimizeMax(int[] nums, int p) {
        Arrays.sort(nums);

        int s = 0;
        int e = nums[nums.length -1];
        int res = Integer.MAX_VALUE;

        while(s <= e) {
            int mid = s + (e-s)/2;

            if(isPossible(nums, mid, p)) {
                res = mid;
                e = mid - 1;
            } else {
                s = mid + 1;
            }
        }

        return res;
    }

    public boolean isPossible(int[] arr, int maxDiff, int pairs) {
        int count = 0;
        int i = 0;

        while(i < arr.length - 1) {
            if(Math.abs(arr[i] - arr[i+1]) <= maxDiff) {
                count++;
                i += 2;
            } else {
                i++;
            }
        }

        return count >= pairs;
    }
}

/*------------------------------
  Time Complexity: O(n)
  Space Complexity: O(1)
-------------------------------*/
class Solution {
    public int buyChoco(int[] prices, int money) {
        int min1 = Integer.MAX_VALUE, min2 = Integer.MAX_VALUE;

        for(int p: prices){
            if(p < min2){
                if(p < min1){
                    min2 = min1;
                    min1 = p;
                }
                else
                    min2 = p;
            }
        }
        int leftover = money - (min1 + min2);
        return (leftover < 0)? money: leftover;
    }
}

