}

/*
    Let N = length of string s, M = length of dictionary
    Time: O(N * M)
    Space: O(N)
*/
class Solution {
    public int minExtraChar(String s, String[] dictionary) {
        int n = s.length();
        int[] dp = new int[n+1];

        Arrays.fill(dp, n);
        dp[0] = 0;

        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j < dictionary.length; ++j) {
                int len = dictionary[j].length();
                if (i >= len && s.substring(i - len, i).equals(dictionary[j])) {
                    dp[i] = Math.min(dp[i], dp[i - len]);
                }
            }
            dp[i] = Math.min(dp[i], dp[i - 1] + 1);
        }

        return dp[n];
    }
}

class Solution {
    Map<String, Integer> dp;
    public int paintWalls(int[] cost, int[] time) {
        int n = cost.length;
        dp = new HashMap<>();
        return dfs(0, cost.length, cost, time);
    }
    private int dfs(int i, int remain, int[] cost, int[] time){
        if(remain <= 0)
            return 0;
        if(i == cost.length)
            return (int) 1e9;
        String s = i + "," + remain;
        if(dp.containsKey(s))
            return dp.get(s);

        int paint = cost[i] + dfs(i+1, remain-1-time[i], cost, time);
        int skip = dfs(i+1, remain, cost, time);
        dp.put(s, Math.min(paint, skip));
        return dp.get(s);
    }
}

class Solution {
    List<List<Integer>> g;
    public long maximumScoreAfterOperations(int[][] edges, int[] values) {
        g = new ArrayList<>();
        for (int i = 0; i < values.length; i++)
            g.add(new ArrayList<>());
        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            g.get(u).add(v);
            g.get(v).add(u);
        }
        long totalSum = 0;
        for (int v : values)
            totalSum += v;

        long minScore = dfs(0, -1, values);

        return totalSum - minScore;
    }

    private long dfs(int node, int parent, int[] values) {
        long childSum = 0;

        for (int neighbour : g.get(node)) {
            if (neighbour == parent)
                continue;
            childSum += dfs(neighbour, node, values);
        }
        if(childSum == 0)
            return values[node];
        long result = Math.min(values[node], childSum);
        return result;
    }
}

class Solution {
    public int maximizeSquareHoleArea(int n, int m, int[] hBars, int[] vBars) {
        Arrays.sort(hBars);
        Arrays.sort(vBars);

        int maxH = getMaxConsecutiveLength(hBars);
        int maxV = getMaxConsecutiveLength(vBars);
        int sqrlen = Math.min(maxH + 1, maxV + 1);

        return sqrlen*sqrlen;
    }
    private int getMaxConsecutiveLength(int[] arr) {
        int maxLen = 0;
        int currentLen = 1;

        for (int i = 1; i < arr.length; i++) {
            if (arr[i] == arr[i - 1] + 1) {
                currentLen++;
            } else {
                maxLen = Math.max(maxLen, currentLen);
                currentLen = 1;
            }
        }
        maxLen = Math.max(maxLen, currentLen);
        return maxLen;
    }
}

public class Solution {

    public long largestPerimeter(int[] nums) {
        Arrays.sort(nums);
        long res = -1, amt = 0;

        for (int i : nums) {
            if (amt > i)
                res = amt + i;
            amt += i;
        }

        return res;
    }
}
